const D = (s) => `<div class="t-formel">${tex(s, true)}</div>`;
const t = (s) => tex(s);

/** Ausführliche Kapitel: Abschnitte mit Überschrift. Eigene Texte, keine fremden Quellen. */
export const LANG = {
  regeln: [
    ['Worum es geht', `<p>Die Ableitung ${t("f'(x)")} sagt, wie steil der Graph von ${t('f')} an der Stelle ${t('x')} ist. Man könnte sie jedes Mal über den Grenzwert des Differenzenquotienten ausrechnen – das ist mühsam. Die Ableitungsregeln sind die Abkürzung: Mit vier Regeln lässt sich fast jede Funktion der Oberstufe ableiten.</p>`],
    ['Potenzregel, Faktor und Summe', `${D("(x^n)'=n\\cdot x^{n-1}")}<p>Der Exponent kommt als Faktor nach vorn und wird um 1 kleiner. Ein Zahlenfaktor bleibt einfach stehen, eine Summe wird Summand für Summand abgeleitet, eine einzelne Zahl fällt weg (sie ändert die Steigung nicht).</p>${D("f(x)=4x^3-5x+7\\quad\\Rightarrow\\quad f'(x)=12x^2-5")}`],
    ['Kettenregel: innen und außen', `<p>Steckt eine Funktion in einer anderen, etwa ${t('(2x+1)^3')}, dann gibt es ein <b>Außen</b> („etwas hoch 3“) und ein <b>Innen</b> (${t('2x+1')}).</p>${D("f(x)=u(v(x))\\quad\\Rightarrow\\quad f'(x)=u'(v(x))\\cdot v'(x)")}<p>In Worten: äußere Ableitung (das Innere bleibt stehen) mal innere Ableitung.</p>${D("\\bigl((2x+1)^3\\bigr)'=3\\,(2x+1)^2\\cdot 2=6\\,(2x+1)^2")}<p>Der häufigste Fehler: die innere Ableitung vergessen. Faustregel: Steht in der Klammer mehr als nur ${t('x')}, immer nachableiten.</p>`],
    ['e-Funktion', `${D("(e^x)'=e^x\\qquad (e^{kx})'=k\\cdot e^{kx}")}<p>Die e-Funktion ist ihre eigene Ableitung. Steht im Exponenten mehr als ${t('x')}, greift wieder die Kettenregel: Der Faktor ${t('k')} kommt nach vorn. Achtung: Die Potenzregel gilt hier <b>nicht</b> – ${t('x')} steht im Exponenten, nicht in der Basis.</p>`],
    ['Produktregel', `${D("(u\\cdot v)'=u'\\cdot v+u\\cdot v'")}<p>Zwei Faktoren, die beide ${t('x')} enthalten, darf man nicht einzeln ableiten und malnehmen. Stattdessen: erst den einen ableiten und den anderen stehen lassen, dann umgekehrt, und beides addieren.</p>${D("f(x)=(x+2)\\,e^{x}\\qquad f'(x)=1\\cdot e^{x}+(x+2)\\cdot e^{x}=(x+3)\\,e^{x}")}`],
    ['So gehst du vor', `<ol><li>Welche Bauart hat die Funktion: Summe, Produkt, Verkettung?</li><li>Die passende Regel hinschreiben und ${t('u')}, ${t('v')} benennen.</li><li>Einzeln ableiten, einsetzen, zusammenfassen.</li><li>Probe mit einem Zahlenwert oder am Graphen: Ist die Ableitung dort positiv, wo der Graph steigt?</li></ol>`],
  ],
  extrema: [
    ['Worum es geht', `<p>Hoch- und Tiefpunkte sind die Stellen, an denen ein Graph „umkehrt“. In Anwendungen sind das der größte Gewinn, der geringste Verbrauch, die höchste Flugbahn. Gefunden werden sie mit der Ableitung.</p>`],
    ['Notwendige Bedingung', `${D("f'(x_0)=0")}<p>An einem Hoch- oder Tiefpunkt ist die Tangente waagerecht. Deshalb sucht man zuerst alle Stellen mit ${t("f'(x)=0")}. Das sind die <b>Kandidaten</b> – mehr nicht: Auch an einem Sattelpunkt ist die Tangente waagerecht.</p>`],
    ['Hinreichende Bedingung', `${D("f'(x_0)=0\\ \\text{und}\\ f''(x_0)<0:\\ \\text{Hochpunkt}\\qquad f'(x_0)=0\\ \\text{und}\\ f''(x_0)>0:\\ \\text{Tiefpunkt}")}<p>Die zweite Ableitung beschreibt die Krümmung. Ist sie negativ, ist der Graph dort nach rechts gekrümmt wie ein Berg – also ein Hochpunkt. Ist ${t("f''(x_0)=0")}, entscheidet der <b>Vorzeichenwechsel</b> von ${t("f'")}: von Plus nach Minus ist es ein Hochpunkt, von Minus nach Plus ein Tiefpunkt, ohne Wechsel ein Sattelpunkt.</p>`],
    ['Durchgerechnetes Beispiel', `${D("f(x)=2x^3-3x^2-12x+4")}<p>Ableiten: ${t("f'(x)=6x^2-6x-12=6\\,(x^2-x-2)=6\\,(x+1)(x-2)")}. Also ${t('x_1=-1')} und ${t('x_2=2')}.</p><p>Zweite Ableitung: ${t("f''(x)=12x-6")}. ${t("f''(-1)=-18<0")}: Hochpunkt. ${t("f''(2)=18>0")}: Tiefpunkt.</p><p>Die y-Werte kommen aus ${t('f')}, nicht aus ${t("f'")}: ${t('f(-1)=11')} und ${t('f(2)=-16')}. Also ${t('H(-1\\mid 11)')} und ${t('T(2\\mid -16)')}.</p>`],
    ['Typische Fehler', `<ul><li>y-Wert mit ${t("f'")} statt mit ${t('f')} berechnet.</li><li>Nur die notwendige Bedingung geprüft und den Sattelpunkt übersehen.</li><li>Bei einem Intervall die Randwerte vergessen: Das größte ${t('f')} kann am Rand liegen.</li></ul>`],
  ],
  integral: [
    ['Worum es geht', `<p>Die Ableitung macht aus einem Bestand eine Änderungsrate. Das Integral geht den Weg zurück: Aus der Änderungsrate wird wieder der Bestand – aus der Geschwindigkeit der Weg, aus dem Zufluss die Wassermenge. Geometrisch ist das Integral eine (mit Vorzeichen gezählte) Fläche zwischen Graph und x-Achse.</p>`],
    ['Stammfunktion', `${D("F'(x)=f(x)\\qquad \\int x^n\\,dx=\\frac{1}{n+1}\\,x^{n+1}+C")}<p>Eine Stammfunktion ${t('F')} ist eine Funktion, deren Ableitung ${t('f')} ist. Beim „Aufleiten“ wird der Exponent um 1 größer und durch den neuen Exponenten geteilt. Die Probe ist immer möglich: ${t('F')} ableiten, es muss ${t('f')} herauskommen.</p>`],
    ['Hauptsatz', `${D("\\int_a^b f(x)\\,dx=F(b)-F(a)")}<p>Obere Grenze einsetzen, untere Grenze einsetzen, abziehen. Die Konstante ${t('C')} fällt dabei weg.</p>${D("\\int_1^3 (2x+1)\\,dx=\\bigl[x^2+x\\bigr]_1^3=(9+3)-(1+1)=10")}`],
    ['Fläche ist nicht gleich Integral', `<p>Liegt der Graph unter der x-Achse, zählt das Integral die Fläche negativ. Wer eine echte <b>Fläche</b> sucht, muss deshalb an den Nullstellen aufteilen und die Beträge addieren.</p>${D("A=\\left|\\int_a^{x_0} f(x)\\,dx\\right|+\\left|\\int_{x_0}^{b} f(x)\\,dx\\right|")}<p>Zwischen zwei Graphen gilt: obere Funktion minus untere Funktion integrieren, zwischen den Schnittstellen.</p>`],
    ['So gehst du vor', `<ol><li>Ist eine Fläche oder ein Integral (Bilanz) gefragt?</li><li>Für Flächen: Nullstellen bzw. Schnittstellen bestimmen.</li><li>Stammfunktion bilden und mit der Ableitung prüfen.</li><li>Grenzen einsetzen – Klammern setzen, besonders bei negativen Zahlen.</li><li>Einheit und Bedeutung im Sachzusammenhang nennen.</li></ol>`],
  ],
  's-labor': [
    ['Worum es geht', `<p>Ein Versuch mit genau zwei Ausgängen (Treffer oder kein Treffer) heißt Bernoulli-Versuch. Wird er ${t('n')}-mal unabhängig mit derselben Trefferwahrscheinlichkeit ${t('p')} wiederholt, zählt die Zufallsgröße ${t('X')} die Treffer – sie ist binomialverteilt.</p>`],
    ['Die Formel und woher sie kommt', `${D("P(X=k)=\\binom{n}{k}\\cdot p^{k}\\cdot (1-p)^{n-k}")}<p>Ein einzelner Pfad mit ${t('k')} Treffern und ${t('n-k')} Nieten hat die Wahrscheinlichkeit ${t('p^k(1-p)^{n-k}')} (Pfadregel). Solche Pfade gibt es ${t('\\binom{n}{k}')} viele, denn so viele Möglichkeiten gibt es, die ${t('k')} Treffer auf ${t('n')} Plätze zu verteilen.</p>`],
    ['Erwartungswert und Streuung', `${D("\\mu=n\\cdot p\\qquad \\sigma=\\sqrt{n\\cdot p\\cdot(1-p)}")}<p>${t('\\mu')} ist die Trefferzahl, die man auf lange Sicht im Mittel erwartet. ${t('\\sigma')} sagt, wie stark die Trefferzahl typischerweise davon abweicht.</p>`],
    ['Mindestens, höchstens, genau', `<p>„Höchstens ${t('k')}“ ist ${t('P(X\\le k)')} (kumuliert, aus Tabelle oder Rechner). „Mindestens ${t('k')}“ rechnet man über das Gegenereignis:</p>${D("P(X\\ge k)=1-P(X\\le k-1)\\qquad P(X\\ge 1)=1-(1-p)^n")}`],
    ['Durchgerechnetes Beispiel', `<p>Ein Basketballer trifft mit ${t('p=0{,}8')}. Er wirft 5-mal. Wahrscheinlichkeit für genau 4 Treffer:</p>${D("P(X=4)=\\binom{5}{4}\\cdot 0{,}8^4\\cdot 0{,}2^1=5\\cdot 0{,}4096\\cdot 0{,}2\\approx 0{,}41")}<p>Mindestens ein Treffer: ${t('1-0{,}2^5\\approx 0{,}9997')}. Erwartete Trefferzahl: ${t('\\mu=5\\cdot 0{,}8=4')}.</p>`],
    ['Wann passt das Modell nicht?', `<p>Wenn sich die Wahrscheinlichkeit von Zug zu Zug ändert (Ziehen ohne Zurücklegen aus einer kleinen Menge) oder wenn die Versuche einander beeinflussen. Im Abitur wird oft gefragt, warum die Binomialverteilung trotzdem als Näherung taugt: bei großer Grundmenge ändert sich ${t('p')} kaum.</p>`],
  ],
  's-bedingt': [
    ['Worum es geht', `<p>Viele Fragen haben eine Vorbedingung: „Wie wahrscheinlich ist die Krankheit, <b>wenn</b> der Test positiv ist?“ Das ist eine bedingte Wahrscheinlichkeit. Sie bezieht sich nicht mehr auf alle, sondern nur noch auf die Gruppe, für die die Bedingung gilt.</p>`],
    ['Definition', `${D("P_B(A)=\\frac{P(A\\cap B)}{P(B)}")}<p>Gelesen: Wahrscheinlichkeit von ${t('A')} unter der Bedingung ${t('B')}. Im Nenner steht die neue Grundgesamtheit ${t('B')}, im Zähler der Teil davon, der auch zu ${t('A')} gehört.</p>`],
    ['Vierfeldertafel als Werkzeug', `<p>Mit absoluten Zahlen wird es anschaulich. 1000 Personen, 50 krank. Der Test erkennt 45 Kranke und schlägt bei 95 Gesunden fälschlich an.</p><table class="t-tafel"><tr><th></th><th>krank</th><th>gesund</th><th>gesamt</th></tr><tr><th>Test positiv</th><td>45</td><td>95</td><td>140</td></tr><tr><th>Test negativ</th><td>5</td><td>855</td><td>860</td></tr><tr><th>gesamt</th><td>50</td><td>950</td><td>1000</td></tr></table><p>Von 140 positiv Getesteten sind nur 45 krank:</p>${D("P_{\\text{positiv}}(\\text{krank})=\\frac{45}{140}\\approx 32\\,\\%")}<p>Obwohl der Test 90 % der Kranken erkennt, ist ein positives Ergebnis hier meist ein Fehlalarm – weil die Krankheit selten ist.</p>`],
    ['Nicht verwechseln', `<p>${t('P_B(A)')} und ${t('P_A(B)')} sind verschiedene Dinge. „90 % der Kranken haben einen positiven Test“ ist nicht dasselbe wie „90 % der positiv Getesteten sind krank“. Frage dich immer: <b>Welche Gruppe ist die Grundgesamtheit?</b></p>`],
    ['Unabhängigkeit', `${D("A,\\ B\\ \\text{unabhängig}\\iff P(A\\cap B)=P(A)\\cdot P(B)\\qquad\\iff P_B(A)=P(A)")}<p>Ändert die Bedingung nichts an der Wahrscheinlichkeit, sind die Ereignisse unabhängig.</p>`],
  ],
  steigung: [
    ['Worum es geht', `<p>Eine Gerade hat überall dieselbe Steigung. Eine Kurve nicht: Sie ist mal steil, mal flach. Die Ableitung beantwortet die Frage „Wie steil ist der Graph genau an dieser einen Stelle?“ – und damit auch „Wie schnell ändert sich die Größe gerade jetzt?“.</p>`],
    ['Von der Sekante zur Tangente', `<p>Zwischen zwei Punkten des Graphen lässt sich die Steigung leicht ausrechnen – das ist die <b>mittlere Änderungsrate</b> (Steigung der Sekante):</p>${D("m=\\frac{f(x_0+h)-f(x_0)}{h}")}<p>Rückt der zweite Punkt immer näher an den ersten (${t('h\\to 0')}), wird aus der Sekante die <b>Tangente</b>. Ihre Steigung ist die <b>momentane Änderungsrate</b>:</p>${D("f'(x_0)=\\lim_{h\\to 0}\\frac{f(x_0+h)-f(x_0)}{h}")}`],
    ['Durchgerechnetes Beispiel', `<p>${t('f(x)=x^2')} an der Stelle ${t('x_0=3')}:</p>${D("\\frac{(3+h)^2-3^2}{h}=\\frac{6h+h^2}{h}=6+h\\ \\xrightarrow{h\\to 0}\\ 6")}<p>Die Tangente bei ${t('x=3')} hat also die Steigung 6. Mit der Potenzregel geht es schneller: ${t("f'(x)=2x")}, also ${t("f'(3)=6")}.</p>`],
    ['Was die Ableitung im Sachzusammenhang bedeutet', `<p>Beschreibt ${t('f(t)')} einen Weg, ist ${t("f'(t)")} die Geschwindigkeit. Beschreibt ${t('f(t)')} einen Wasserstand, ist ${t("f'(t)")} die Zu- oder Abflussrate. Die Einheit der Ableitung ist immer „Einheit von ${t('f')} pro Einheit von ${t('x')}“ – zum Beispiel Meter pro Sekunde.</p>`],
    ['Vorzeichen lesen', `<ul><li>${t("f'(x)>0")}: Der Graph steigt.</li><li>${t("f'(x)<0")}: Der Graph fällt.</li><li>${t("f'(x)=0")}: waagerechte Tangente – Kandidat für Hoch-, Tief- oder Sattelpunkt.</li></ul>`],
  ],
  kurve: [
    ['Worum es geht', `<p>Eine Kurvendiskussion ist ein Steckbrief des Graphen: Wo steigt er, wo fällt er, wo dreht er seine Krümmung, was passiert weit außen? Jede dieser Fragen hat ein festes Werkzeug.</p>`],
    ['Monotonie', `<p>Das Vorzeichen von ${t("f'")} entscheidet. Man bestimmt die Nullstellen von ${t("f'")} und prüft in jedem Abschnitt dazwischen ein Vorzeichen.</p>${D("f'(x)>0\\ \\Rightarrow\\ \\text{streng monoton steigend}\\qquad f'(x)<0\\ \\Rightarrow\\ \\text{streng monoton fallend}")}`],
    ['Krümmung und Wendepunkte', `${D("f''(x_W)=0\\ \\text{und}\\ f'''(x_W)\\ne 0\\ \\Rightarrow\\ \\text{Wendestelle}")}<p>${t("f''>0")} heißt Linkskurve, ${t("f''<0")} Rechtskurve. An der Wendestelle wechselt die Krümmung – und die Steigung ist dort am größten oder am kleinsten. Deshalb ist der Wendepunkt in Anwendungen der Moment der stärksten Zu- oder Abnahme.</p>`],
    ['Symmetrie', `${D("f(-x)=f(x):\\ \\text{achsensymmetrisch zur y-Achse}\\qquad f(-x)=-f(x):\\ \\text{punktsymmetrisch zum Ursprung}")}<p>Bei ganzrationalen Funktionen reicht ein Blick auf die Exponenten: nur gerade Exponenten (und Zahlen) → achsensymmetrisch, nur ungerade → punktsymmetrisch, gemischt → keine dieser Symmetrien.</p>`],
    ['Verhalten im Unendlichen', `<p>Für sehr große ${t('|x|')} bestimmt bei ganzrationalen Funktionen allein der Summand mit dem höchsten Exponenten das Verhalten. Bei ${t('f(x)=-2x^3+5x')} gilt: für ${t('x\\to\\infty')} geht ${t('f(x)\\to -\\infty')}, für ${t('x\\to -\\infty')} geht ${t('f(x)\\to\\infty')}.</p><p>Bei e-Funktionen gewinnt ${t('e^x')} gegen jede Potenz: ${t('x^2\\cdot e^{-x}\\to 0')} für ${t('x\\to\\infty')}.</p>`],
    ['Reihenfolge für die Prüfung', `<ol><li>Definitionsmenge, Symmetrie, Verhalten außen</li><li>Nullstellen</li><li>Extrempunkte (mit ${t("f'")} und ${t("f''")})</li><li>Wendepunkte (mit ${t("f''")} und ${t("f'''")})</li><li>Skizze mit allen gefundenen Punkten</li></ol>`],
  ],
  expln: [
    ['Worum es geht', `<p>Wächst oder fällt eine Größe in gleichen Zeitspannen immer um denselben <b>Faktor</b>, ist das exponentiell: Zinseszins, Bakterien, radioaktiver Zerfall, abkühlender Kaffee. Der natürliche Logarithmus ist das Werkzeug, um solche Gleichungen nach der Zeit aufzulösen.</p>`],
    ['Die Funktion', `${D("f(t)=a\\cdot e^{k\\,t}")}<p>${t('a')} ist der Anfangswert (${t('t=0')}), ${t('k')} die Wachstumskonstante: ${t('k>0')} Wachstum, ${t('k<0')} Zerfall. Die Änderungsrate ist proportional zum Bestand:</p>${D("f'(t)=k\\cdot f(t)")}`],
    ['Der Logarithmus als Umkehrung', `${D("e^{x}=b\\iff x=\\ln b\\qquad \\ln(e^x)=x\\qquad e^{\\ln x}=x")}<p>${t('\\ln b')} ist die Hochzahl, mit der man ${t('e')} potenzieren muss, um ${t('b')} zu bekommen. Merke: ${t('\\ln 1=0')} und ${t('\\ln e=1')}. Für Zahlen zwischen 0 und 1 ist der Logarithmus negativ, für Zahlen ≤ 0 gibt es keinen.</p>`],
    ['Verdopplungs- und Halbwertszeit', `${D("T_2=\\frac{\\ln 2}{k}\\qquad T_{1/2}=\\frac{\\ln 2}{|k|}")}<p>Herleitung: ${t('a\\,e^{kT}=2a')} führt auf ${t('e^{kT}=2')}, also ${t('kT=\\ln 2')}. Bemerkenswert: Die Verdopplungszeit hängt nicht vom Anfangswert ab.</p>`],
    ['Durchgerechnetes Beispiel', `<p>Ein Kapital von 2000 € wächst nach ${t('f(t)=2000\\cdot e^{0{,}03t}')} (${t('t')} in Jahren). Wann sind es 3000 €?</p>${D("2000\\,e^{0{,}03t}=3000\\ \\Rightarrow\\ e^{0{,}03t}=1{,}5\\ \\Rightarrow\\ t=\\frac{\\ln 1{,}5}{0{,}03}\\approx 13{,}5")}<p>Nach etwa 13,5 Jahren. Probe: ${t('2000\\cdot e^{0{,}405}\\approx 3000')}.</p>`],
    ['Ableiten', `${D("(e^{kx})'=k\\,e^{kx}\\qquad (\\ln x)'=\\frac{1}{x}")}<p>Bei ${t('\\ln')} mit innerer Funktion gilt die Kettenregel: ${t("(\\ln(2x+1))'=\\tfrac{2}{2x+1}")}.</p>`],
  ],
  's-baum': [
    ['Worum es geht', `<p>Viele Zufallsversuche laufen in mehreren Schritten ab: zweimal würfeln, drei Kugeln ziehen, Hin- und Rückspiel. Ein Baumdiagramm ordnet alle möglichen Abläufe – und zwei einfache Regeln liefern jede gesuchte Wahrscheinlichkeit.</p>`],
    ['Aufbau', `<p>Jede Stufe ist ein Teilversuch. Von jedem Knoten gehen Äste zu den möglichen Ergebnissen, an jedem Ast steht seine Wahrscheinlichkeit. <b>Die Äste, die von einem Knoten ausgehen, ergeben zusammen immer 1.</b> Ein Weg von der Wurzel bis ans Ende heißt Pfad.</p>`],
    ['Die zwei Pfadregeln', `${D("\\text{1. Pfadregel: entlang eines Pfades multiplizieren}")}${D("\\text{2. Pfadregel: passende Pfade addieren}")}<p>Die erste Regel gibt die Wahrscheinlichkeit für einen bestimmten Ablauf. Gehören mehrere Abläufe zum gesuchten Ereignis, werden ihre Wahrscheinlichkeiten addiert.</p>`],
    ['Mit oder ohne Zurücklegen', `<p><b>Mit Zurücklegen</b> bleibt die Urne gleich – die Wahrscheinlichkeiten sind auf jeder Stufe dieselben. <b>Ohne Zurücklegen</b> fehlt nach jedem Zug eine Kugel: Zähler und Nenner ändern sich.</p>${D("\\text{4 rote, 2 blaue, ohne Zurücklegen:}\\qquad P(\\text{rot, rot})=\\frac{4}{6}\\cdot\\frac{3}{5}=\\frac{2}{5}")}`],
    ['Durchgerechnetes Beispiel', `<p>Dieselbe Urne, zwei Züge ohne Zurücklegen. Wahrscheinlichkeit für zwei verschiedene Farben:</p>${D("P=\\frac{4}{6}\\cdot\\frac{2}{5}+\\frac{2}{6}\\cdot\\frac{4}{5}=\\frac{8}{30}+\\frac{8}{30}=\\frac{8}{15}")}<p>Zwei Pfade gehören dazu (rot–blau und blau–rot). Wer nur einen rechnet, macht den häufigsten Fehler bei dieser Aufgabe.</p>`],
    ['Abkürzung über das Gegenereignis', `${D("P(\\text{mindestens ein Treffer})=1-P(\\text{kein Treffer})")}<p>Statt viele Pfade zu addieren, rechnet man den einen Pfad ohne Treffer aus und zieht ihn von 1 ab.</p>`],
  ],
  'g-gerade': [
    ['Worum es geht', `<p>Eine Gerade im Raum lässt sich nicht mit ${t('y=mx+b')} beschreiben – dafür braucht man Vektoren. Die Idee: Man startet an einem Punkt und läuft beliebig weit in eine feste Richtung.</p>`],
    ['Parameterform', `${D("g:\\ \\vec x=\\vec p+t\\cdot\\vec u")}<p>${t('\\vec p')} ist der <b>Stützvektor</b> (führt zu einem Punkt der Geraden), ${t('\\vec u')} der <b>Richtungsvektor</b>. Jeder Wert des Parameters ${t('t')} liefert genau einen Punkt. Durch zwei Punkte ${t('A')} und ${t('B')} geht die Gerade mit ${t('\\vec p=\\overrightarrow{OA}')} und ${t('\\vec u=\\overrightarrow{AB}')}.</p>`],
    ['Punktprobe', `<p>Liegt ${t('Q')} auf ${t('g')}? Man setzt ${t('Q')} ein und löst jede der drei Zeilen nach ${t('t')} auf. Kommt überall <b>dasselbe</b> ${t('t')} heraus, liegt der Punkt auf der Geraden.</p>${D("\\begin{pmatrix}7\\\\4\\\\1\\end{pmatrix}=\\begin{pmatrix}1\\\\0\\\\3\\end{pmatrix}+t\\begin{pmatrix}3\\\\2\\\\-1\\end{pmatrix}\\ \\Rightarrow\\ t=2,\\ t=2,\\ t=2\\ \\checkmark")}`],
    ['Lage zweier Geraden', `<p>Erst die Richtungsvektoren vergleichen:</p><ul><li><b>Vielfache voneinander:</b> parallel – oder sogar identisch, wenn ein Punkt der einen auf der anderen liegt.</li><li><b>Keine Vielfachen:</b> gleichsetzen. Hat das Gleichungssystem eine Lösung, schneiden sich die Geraden; hat es keine, sind sie <b>windschief</b> (sie laufen aneinander vorbei).</li></ul>`],
    ['Schnittpunkt berechnen', `<p>Gleichsetzen ergibt drei Gleichungen für zwei Parameter. Zwei Gleichungen liefern ${t('t')} und ${t('s')}, die dritte ist die <b>Probe</b>. Wichtig: verschiedene Buchstaben für die Parameter der beiden Geraden verwenden. Den Schnittpunkt bekommt man, indem man ${t('t')} in die erste Gerade einsetzt.</p>`],
  ],
  'g-ebene': [
    ['Worum es geht', `<p>Eine Ebene ist eine unendlich ausgedehnte, flache Fläche im Raum. Die Koordinatenform beschreibt sie mit einer einzigen Gleichung – damit lässt sich schnell prüfen, ob ein Punkt in der Ebene liegt und wo eine Gerade sie trifft.</p>`],
    ['Koordinatenform und Normalenvektor', `${D("E:\\ a\\,x_1+b\\,x_2+c\\,x_3=d\\qquad \\vec n=\\begin{pmatrix}a\\\\b\\\\c\\end{pmatrix}")}<p>Die drei Zahlen vor ${t('x_1,x_2,x_3')} bilden den <b>Normalenvektor</b>. Er steht senkrecht auf der Ebene und legt ihre Lage im Raum fest; ${t('d')} verschiebt die Ebene entlang dieser Richtung.</p>`],
    ['Punktprobe', `<p>Koordinaten des Punktes einsetzen. Stimmt die Gleichung, liegt der Punkt in der Ebene.</p>${D("E:\\ 2x_1-x_2+2x_3=6,\\quad P(1\\mid 2\\mid 3)\\qquad 2\\cdot1-2+2\\cdot3=6\\ \\checkmark")}`],
    ['Normalenvektor aus zwei Richtungen', `<p>Sind zwei Richtungsvektoren ${t('\\vec u')} und ${t('\\vec v')} der Ebene bekannt, liefert das Kreuzprodukt einen Vektor, der auf beiden senkrecht steht:</p>${D("\\vec n=\\vec u\\times\\vec v=\\begin{pmatrix}u_2v_3-u_3v_2\\\\u_3v_1-u_1v_3\\\\u_1v_2-u_2v_1\\end{pmatrix}")}<p>Probe: ${t('\\vec n\\cdot\\vec u=0')} und ${t('\\vec n\\cdot\\vec v=0')}.</p>`],
    ['Schnittpunkt Gerade – Ebene', `<p>Die Gerade zeilenweise in die Ebenengleichung einsetzen, nach ${t('t')} auflösen, ${t('t')} zurück in die Gerade.</p>${D("g:\\ \\vec x=\\begin{pmatrix}1\\\\0\\\\2\\end{pmatrix}+t\\begin{pmatrix}1\\\\1\\\\0\\end{pmatrix},\\quad E:\\ x_1+x_2+x_3=7")}<p>${t('(1+t)+t+2=7')}, also ${t('t=2')} und ${t('S(3\\mid 2\\mid 2)')}. Fällt ${t('t')} heraus, ist die Gerade parallel zur Ebene (falsche Aussage) oder liegt darin (wahre Aussage).</p>`],
  ],
  extremwert: [
    ['Worum es geht', `<p>„Wie wird die Fläche am größten?“, „Wann ist der Materialverbrauch am kleinsten?“ – das sind Extremwertaufgaben. Die Rechnung ist dieselbe wie bei Extrempunkten. Die eigentliche Arbeit steckt davor: aus dem Text eine Funktion mit <b>einer</b> Variablen zu bauen.</p>`],
    ['Zwei Zutaten', `<p>Die <b>Hauptbedingung</b> ist die Formel für die Größe, die möglichst groß oder klein werden soll (Fläche, Volumen, Kosten). Sie enthält meist zwei Variablen. Die <b>Nebenbedingung</b> beschreibt, was fest vorgegeben ist (Zaunlänge, Umfang, Materialmenge). Mit ihr wird eine Variable durch die andere ersetzt – übrig bleibt die <b>Zielfunktion</b>.</p>`],
    ['Durchgerechnetes Beispiel', `<p>Mit 40 m Zaun soll an einer Hauswand ein rechteckiges Gehege entstehen. Die Wand ersetzt eine Seite. Die beiden Seiten senkrecht zur Wand heißen ${t('x')}, die Seite gegenüber der Wand ${t('y')}.</p>${D('A=x\\cdot y')}<p>Nebenbedingung (der Zaun reicht für drei Seiten):</p>${D('2x+y=40\\ \\Rightarrow\\ y=40-2x')}${D("A(x)=x\\,(40-2x)=40x-2x^2")}${D("0<x<20")}<p>Ableiten und null setzen: ${t("A'(x)=40-4x=0")}, also ${t('x=10')}. Wegen ${t("A''(x)=-4<0")} ist es ein Maximum. Dann ist ${t('y=40-2\\cdot 10=20')}.</p><p><b>Antwort:</b> Das Gehege wird 10 m tief und 20 m breit und hat dann 200 m² Fläche.</p>`],
    ['Der Rand zählt mit', `<p>Die Zielfunktion gilt nur für sinnvolle Werte – hier ${t('0<x<20')}, sonst wäre eine Seite negativ. Ist der Bereich abgeschlossen (etwa „${t('x')} höchstens 8“), muss der Wert am Rand mit dem Extremum verglichen werden: Das größte ${t('A')} kann am Rand liegen, auch wenn dort ${t("A'\\ne 0")} ist.</p>`],
    ['So gehst du vor', `<ol><li>Skizze zeichnen, Variablen benennen.</li><li>Hauptbedingung aufschreiben: Was soll extrem werden?</li><li>Nebenbedingung aufschreiben und nach einer Variablen auflösen.</li><li>Einsetzen – die Zielfunktion hat jetzt nur noch eine Variable. Bereich angeben.</li><li>Ableiten, null setzen, Art des Extremums prüfen, Rand vergleichen.</li><li>Fehlende Größe ausrechnen und einen Antwortsatz mit Einheit schreiben.</li></ol>`],
    ['Typische Fehler', `<ul><li>Die Hauptbedingung mit zwei Variablen abgeleitet, ohne vorher einzusetzen.</li><li>Nach der falschen Größe gefragt: Gesucht ist oft ${t('x')} <b>und</b> der größte Wert selbst.</li><li>Den Bereich vergessen und eine Lösung angegeben, die es gar nicht geben kann.</li></ul>`],
  ],
  's-test': [
    ['Worum es geht', `<p>Jemand behauptet etwas über eine Wahrscheinlichkeit – „höchstens 10 % Ausschuss“, „die Münze ist fair“. Ein Hypothesentest legt <b>vor</b> der Stichprobe eine Regel fest, bei welchen Ergebnissen man der Behauptung nicht mehr glaubt. Sicherheit gibt es dabei nie, aber das Risiko eines Irrtums wird begrenzt.</p>`],
    ['Die Begriffe', `<p>Die <b>Nullhypothese</b> ${t('H_0')} ist die Behauptung, an der man festhält, solange nichts deutlich dagegen spricht. Die <b>Gegenhypothese</b> ${t('H_1')} ist das, was man vermutet. Das <b>Signifikanzniveau</b> ${t('\\alpha')} (oft 5 %) ist das Risiko, das man höchstens eingehen will, ${t('H_0')} zu Unrecht abzulehnen. Der <b>Ablehnungsbereich</b> enthält alle Ergebnisse, bei denen ${t('H_0')} verworfen wird.</p>`],
    ['Rechtsseitiger Test', `<p>Vermutet man, dass die Wahrscheinlichkeit in Wahrheit <b>größer</b> ist, sprechen <b>große</b> Trefferzahlen gegen ${t('H_0')}. Gesucht ist die kleinste Zahl ${t('k')}, für die gilt:</p>${D('P(X\\ge k)=1-P(X\\le k-1)\\le\\alpha')}${D('\\text{Ablehnungsbereich: }\\{k;\\,\\dots;\\,n\\}')}<p>Gerechnet wird immer mit der Wahrscheinlichkeit aus ${t('H_0')} – man tut so, als stimme die Behauptung.</p>`],
    ['Durchgerechnetes Beispiel', `<p>Ein Hersteller behauptet: höchstens 10 % Ausschuss. Geprüft werden 50 Teile, ${t('\\alpha=5\\,\\%')}.</p>${D('H_0:\\ p\\le 0{,}1')}${D('H_1:\\ p>0{,}1')}${D('X\\sim B(50;\\,0{,}1)')}<p>Aus der Tabelle: ${t('P(X\\ge 9)=1-P(X\\le 8)\\approx 0{,}058')} – noch zu groß. ${t('P(X\\ge 10)=1-P(X\\le 9)\\approx 0{,}025\\le 0{,}05')} – passt.</p><p><b>Entscheidungsregel:</b> Bei 10 oder mehr defekten Teilen wird die Behauptung des Herstellers abgelehnt, sonst nicht.</p>`],
    ['Zwei Arten von Fehlern', `<p><b>Fehler 1. Art:</b> ${t('H_0')} stimmt, wird aber abgelehnt. Seine Wahrscheinlichkeit ist höchstens ${t('\\alpha')} – im Beispiel etwa 2,5 %. <b>Fehler 2. Art:</b> ${t('H_0')} ist falsch, wird aber nicht abgelehnt. Seine Wahrscheinlichkeit hängt davon ab, wie groß ${t('p')} wirklich ist: Bei ${t('p=0{,}2')} wäre sie ${t('P(X\\le 9)\\approx 0{,}44')}, gerechnet mit ${t('B(50;\\,0{,}2)')}.</p><p>Macht man ${t('\\alpha')} kleiner, wird der Ablehnungsbereich kleiner – und der Fehler 2. Art größer. Beide gleichzeitig verkleinern geht nur mit einer größeren Stichprobe.</p>`],
    ['Typische Fehler', `<ul><li>${t('\\alpha')} ist <b>nicht</b> die Wahrscheinlichkeit, dass ${t('H_0')} stimmt.</li><li>„${t('H_0')} wird nicht abgelehnt“ heißt nicht „${t('H_0')} ist bewiesen“.</li><li>Grenze um eins verrutscht: ${t('P(X\\ge k)')} gehört zu ${t('P(X\\le k-1)')}, nicht zu ${t('P(X\\le k)')}.</li><li>Die Hypothesen erst nach dem Blick auf die Daten gewählt.</li></ul>`],
  ],
  's-verteilung': [
    ['Worum es geht', `<p>Eine Verteilung sagt, welche Werte eine Zufallsgröße mit welcher Wahrscheinlichkeit annimmt. Meist interessiert kein einzelner Wert, sondern ein Bereich: höchstens, mindestens, zwischen. Dafür gibt es drei Werkzeuge – kumulierte Tabellen, die Sigma-Regeln und die Normalverteilung.</p>`],
    ['Bereiche mit kumulierten Werten', `<p>Tabelle und Rechner liefern ${t('P(X\\le k)')}. Alles andere wird daraus zusammengesetzt:</p>${D('P(X\\ge k)=1-P(X\\le k-1)')}${D('\\begin{aligned}P(a\\le X\\le b)&=P(X\\le b)\\\\&\\quad-P(X\\le a-1)\\end{aligned}')}<p>Der Schritt um eins zurück ist die häufigste Fehlerquelle: Bei ganzen Zahlen gehört die Grenze ${t('a')} selbst noch zum Bereich, deshalb wird erst ab ${t('a-1')} abgezogen.</p>`],
    ['Sigma-Regeln', `${D('P(\\mu-\\sigma\\le X\\le\\mu+\\sigma)\\approx 68{,}3\\,\\%')}${D('P(\\mu-2\\sigma\\le X\\le\\mu+2\\sigma)\\approx 95{,}4\\,\\%')}<p>Im Abstand von drei ${t('\\sigma')} um den Erwartungswert liegen sogar etwa 99,7 %. Für eine Binomialverteilung sind die Regeln brauchbar, wenn ${t('\\sigma>3')} ist.</p><p>Beispiel: 100 Münzwürfe, ${t('\\mu=50')}, ${t('\\sigma=\\sqrt{100\\cdot 0{,}5\\cdot 0{,}5}=5')}. Mit rund 95 % Wahrscheinlichkeit fällt zwischen 40- und 60-mal Kopf.</p>`],
    ['Normalverteilung', `<p>Viele Messgrößen (Körpergröße, Füllmenge, Messfehler) verteilen sich wie eine Glocke um den Mittelwert. Die Kurve ist durch ${t('\\mu')} (Lage der Mitte) und ${t('\\sigma')} (Breite) festgelegt. Wahrscheinlichkeiten sind <b>Flächen</b> unter der Kurve; ein einzelner Wert hat die Wahrscheinlichkeit 0, deshalb ist es hier egal, ob „kleiner“ oder „kleiner gleich“ dasteht.</p>${D('z=\\frac{x-\\mu}{\\sigma}')}${D('P(X\\le x)=\\Phi(z)')}<p>Das Standardisieren rechnet jeden Wert in „Abstand vom Mittelwert, gemessen in ${t('\\sigma')}“ um. Dann genügt eine einzige Tabelle für alle Normalverteilungen.</p>`],
    ['Durchgerechnetes Beispiel', `<p>Die Körpergröße in einer Gruppe ist normalverteilt mit ${t('\\mu=170')} cm und ${t('\\sigma=8')} cm. Wie wahrscheinlich ist höchstens 182 cm?</p>${D('z=\\frac{182-170}{8}=1{,}5')}${D('P(X\\le 182)=\\Phi(1{,}5)\\approx 0{,}933')}<p>Zwischen 162 cm und 178 cm liegt genau der Bereich ${t('\\mu\\pm\\sigma')} – also etwa 68 %, ganz ohne Tabelle.</p>`],
    ['Typische Fehler', `<ul><li>Bei „mindestens“ mit ${t('P(X\\le k)')} statt ${t('P(X\\le k-1)')} gerechnet.</li><li>Für negative ${t('z')} die Symmetrie vergessen: ${t('\\Phi(-z)=1-\\Phi(z)')}.</li><li>Varianz und Standardabweichung verwechselt: ${t('\\sigma')} ist die Wurzel der Varianz.</li></ul>`],
  ],
  'g-skalar': [
    ['Worum es geht', `<p>Das Skalarprodukt macht aus zwei Vektoren <b>eine Zahl</b>. Diese Zahl verrät, wie die Vektoren zueinander stehen – vor allem, ob sie senkrecht aufeinander stehen. Damit ist es das wichtigste Werkzeug für Winkel, Normalenvektoren und Abstände.</p>`],
    ['So wird gerechnet', `${D('\\vec a\\cdot\\vec b=a_1b_1+a_2b_2+a_3b_3')}<p>Gleiche Koordinaten malnehmen, alles addieren.</p>${D('\\begin{pmatrix}2\\\\-1\\\\3\\end{pmatrix}\\cdot\\begin{pmatrix}4\\\\2\\\\-2\\end{pmatrix}=8-2-6=0')}`],
    ['Was die Zahl bedeutet', `${D('\\vec a\\cdot\\vec b=|\\vec a|\\cdot|\\vec b|\\cdot\\cos\\varphi')}<p>Die Längen sind positiv, also entscheidet der Kosinus über das Vorzeichen: Ist das Skalarprodukt positiv, ist der Winkel spitz; ist es negativ, ist er stumpf. Und ist es <b>null</b>, dann ist ${t('\\cos\\varphi=0')} – die Vektoren stehen senkrecht aufeinander. Im Beispiel oben ist das der Fall.</p>`],
    ['Winkel berechnen', `${D('\\cos\\varphi=\\frac{\\vec a\\cdot\\vec b}{|\\vec a|\\cdot|\\vec b|}')}<p>Für ${t('\\vec a=(1\\mid 2\\mid 2)')} und ${t('\\vec b=(2\\mid 0\\mid 1)')}: Skalarprodukt ${t('2+0+2=4')}, Längen ${t('|\\vec a|=\\sqrt{9}=3')} und ${t('|\\vec b|=\\sqrt 5')}.</p>${D('\\cos\\varphi=\\frac{4}{3\\cdot\\sqrt 5}\\approx 0{,}596')}<p>Daraus folgt ${t('\\varphi\\approx 53{,}4^\\circ')}.</p>`],
    ['Wofür man es braucht', `<ul><li><b>Rechter Winkel?</b> Skalarprodukt ausrechnen – null heißt ja.</li><li><b>Normalenvektor einer Ebene:</b> Er steht senkrecht auf beiden Spannvektoren, beide Skalarprodukte sind null.</li><li><b>Winkel zwischen Geraden:</b> mit den Richtungsvektoren; weil der Winkel höchstens 90° sein soll, nimmt man den Betrag des Skalarprodukts.</li></ul>`],
    ['Typische Fehler', `<ul><li>Als Ergebnis einen Vektor aufgeschrieben – es ist immer eine Zahl.</li><li>Bei der Länge die Wurzel vergessen.</li><li>Taschenrechner auf Bogenmaß statt auf Grad.</li></ul>`],
  ],
  'g-mass': [
    ['Worum es geht', `<p>Wie weit ist ein Punkt von einer Ebene entfernt? Unter welchem Winkel trifft eine Gerade auf eine Fläche? Solche Fragen stehen in fast jeder Geometrie-Aufgabe mit Sachbezug – Dachneigung, Flughöhe, Abstand eines Masts zum Hang.</p>`],
    ['Abstand zweier Punkte', `${D('|\\overrightarrow{AB}|=\\sqrt{d_1^{\\,2}+d_2^{\\,2}+d_3^{\\,2}}')}<p>Dabei ist ${t('d_1=b_1-a_1')} und so weiter – die Koordinaten des Verbindungsvektors. Das ist der Satz des Pythagoras im Raum: Verbindungsvektor bilden, Koordinaten quadrieren, addieren, Wurzel ziehen.</p>`],
    ['Abstand Punkt – Ebene', `<p>Der Abstand ist die Länge des <b>kürzesten</b> Wegs, und der führt senkrecht auf die Ebene – also in Richtung des Normalenvektors. Liegt die Ebene in Koordinatenform ${t('n_1x_1+n_2x_2+n_3x_3=d')} vor, gibt es eine fertige Formel:</p>${D('\\text{Abstand}=\\frac{|\\,n_1p_1+n_2p_2+n_3p_3-d\\,|}{|\\vec n|}')}<p>Beispiel: ${t('E:\\ 2x_1-x_2+2x_3=6')} und ${t('P(3\\mid 1\\mid 4)')}. Zähler: ${t('|6-1+8-6|=7')}. Nenner: ${t('|\\vec n|=\\sqrt{4+1+4}=3')}. Abstand ${t('\\tfrac 73\\approx 2{,}33')}.</p>`],
    ['Mit Lotfußpunkt', `<p>Soll auch der Punkt auf der Ebene angegeben werden, der ${t('P')} am nächsten liegt, geht man den Weg zu Fuß: Lotgerade durch ${t('P')} mit dem Normalenvektor als Richtung, in die Ebene einsetzen, nach ${t('t')} auflösen.</p>${D('g:\\ \\vec x=\\begin{pmatrix}3\\\\1\\\\4\\end{pmatrix}+t\\begin{pmatrix}2\\\\-1\\\\2\\end{pmatrix}')}${D('2(3+2t)-(1-t)+2(4+2t)=6')}<p>Ausmultipliziert: ${t('13+9t=6')}, also ${t('t=-\\tfrac 79')}. Der Lotfußpunkt ist ${t('F(\\tfrac{13}{9}\\mid\\tfrac{16}{9}\\mid\\tfrac{22}{9})')}, der Abstand ${t('|t|\\cdot|\\vec n|=\\tfrac 79\\cdot 3=\\tfrac 73')} – dasselbe wie mit der Formel.</p>`],
    ['Winkel', `${D('\\cos\\varphi=\\frac{|\\vec u\\cdot\\vec v|}{|\\vec u|\\cdot|\\vec v|}')}${D('\\sin\\varphi=\\frac{|\\vec u\\cdot\\vec n|}{|\\vec u|\\cdot|\\vec n|}')}<p>Die erste Formel gilt für zwei Geraden (mit den Richtungsvektoren) und für zwei Ebenen (mit den Normalenvektoren). Die zweite gilt für Gerade und Ebene – dort steht der <b>Sinus</b>: Der Normalenvektor misst den Winkel zur Senkrechten – der gesuchte Winkel zur Ebene ist die Ergänzung auf 90°.</p>`],
    ['Typische Fehler', `<ul><li>Den Betrag im Zähler vergessen – ein Abstand ist nie negativ.</li><li>Bei Gerade und Ebene Kosinus statt Sinus verwendet.</li><li>Die Ebene nicht erst in Koordinatenform gebracht.</li><li>Durch ${t('|\\vec n|^2')} statt durch ${t('|\\vec n|')} geteilt.</li></ul>`],
  ],
  formen: [
    ['Worum es geht', `<p>Fast jede Funktion der Oberstufe entsteht aus einer einfachen Grundform, die gestreckt, verschoben oder gespiegelt wird. Wer weiß, was jeder Parameter mit dem Graphen macht, kann eine Funktion am Bild ablesen – und umgekehrt den Graphen skizzieren, ohne eine Wertetabelle zu rechnen.</p>`],
    ['Gerade', `${D('f(x)=m\\,x+b')}<p>${t('m')} ist die Steigung: ein Schritt nach rechts, ${t('m')} Schritte nach oben (bei negativem ${t('m')} nach unten). ${t('b')} ist der Schnittpunkt mit der y-Achse. Aus zwei Punkten bekommt man die Steigung über den Höhenunterschied geteilt durch den Abstand nach rechts:</p>${D('m=\\frac{y_2-y_1}{x_2-x_1}')}`],
    ['Parabel in Scheitelform', `${D('f(x)=a\\,(x-d)^2+e')}<p>Der Scheitel liegt bei ${t('S(d\\mid e)')}. Ist ${t('a')} positiv, ist die Parabel nach oben offen, sonst nach unten. Je größer der Betrag von ${t('a')}, desto schmaler wird sie.</p><p>Die Falle steckt im Vorzeichen: ${t('(x-3)^2')} verschiebt um 3 nach <b>rechts</b>, ${t('(x+3)^2')} nach links.</p>`],
    ['Sinus', `${D('f(x)=a\\cdot\\sin\\bigl(b\\,(x-c)\\bigr)+d')}<p>${t('|a|')} ist die Amplitude (wie weit es nach oben und unten ausschlägt), ${t('d')} die Mittellage. Die Periode ist ${t('\\tfrac{2\\pi}{b}')}: Ein größeres ${t('b')} macht die Wellen enger. ${t('c')} verschiebt nach rechts.</p>`],
    ['Die Regel dahinter', `<p>Was <b>außen</b> an der Funktion steht, wirkt in y-Richtung und so, wie man es erwartet: ${t('a\\cdot f(x)')} streckt, ${t('f(x)+e')} schiebt nach oben. Was <b>innen</b> beim ${t('x')} steht, wirkt in x-Richtung und genau umgekehrt: ${t('f(x-d)')} schiebt nach rechts, ${t('f(b\\cdot x)')} staucht auf den ${t('\\tfrac 1b')}-fachen Abstand.</p>`],
    ['Durchgerechnetes Beispiel', `${D('f(x)=2\\,(x+1)^2-3')}<p>Scheitel ${t('S(-1\\mid -3)')}, nach oben offen, schmaler als die Normalparabel. Nullstellen: ${t('2(x+1)^2=3')}, also ${t('(x+1)^2=1{,}5')} und damit ${t('x=-1\\pm\\sqrt{1{,}5}')}, gerundet ${t('x_1\\approx 0{,}22')} und ${t('x_2\\approx -2{,}22')}.</p>`],
    ['Typische Fehler', `<ul><li>Verschiebung in x-Richtung mit falschem Vorzeichen abgelesen.</li><li>Bei der Periode ${t('2\\pi\\cdot b')} statt ${t('2\\pi:b')} gerechnet.</li><li>Steigung als „rechts durch hoch“ statt „hoch durch rechts“.</li></ul>`],
  ],
  zeichnen: [
    ['Worum es geht', `<p>Die Ableitung ${t("f'")} gibt an jeder Stelle die Steigung von ${t('f')} an. Aus dem Bild von ${t('f')} lässt sich deshalb das Bild von ${t("f'")} skizzieren – ganz ohne Rechnung. Im Abitur wird das gern verlangt, weil es zeigt, ob man die Ableitung verstanden hat.</p>`],
    ['Was man am Graphen abliest', `${D("f\\ \\text{steigt}\\ \\Rightarrow\\ f'>0\\qquad f\\ \\text{fällt}\\ \\Rightarrow\\ f'<0")}<p>An einem Hoch- oder Tiefpunkt von ${t('f')} ist die Tangente waagerecht: Dort hat ${t("f'")} eine <b>Nullstelle</b> und wechselt das Vorzeichen. An einem Wendepunkt ist ${t('f')} am steilsten (oder am flachsten): Dort hat ${t("f'")} einen <b>Hoch- oder Tiefpunkt</b>.</p>`],
    ['So gehst du vor', `<ol><li>Extremstellen von ${t('f')} markieren – das werden die Nullstellen von ${t("f'")}.</li><li>Dazwischen das Vorzeichen festlegen: steigend heißt über der x-Achse, fallend darunter.</li><li>Wendestellen von ${t('f')} markieren – dort bekommt ${t("f'")} seine Hoch- und Tiefpunkte.</li><li>Abschätzen, wie steil ${t('f')} ist: sehr steil heißt großer Wert von ${t("f'")}.</li><li>Alles zu einer glatten Kurve verbinden.</li></ol>`],
    ['Ein Grad weniger', `<p>Bei ganzrationalen Funktionen hat die Ableitung einen Grad weniger: Aus einer Parabel wird eine Gerade, aus einer Funktion dritten Grades (mit „Berg und Tal“) eine Parabel. Das ist eine gute Kontrolle für die Skizze.</p>`],
    ['Der Rückweg', `<p>Von ${t("f'")} auf ${t('f')} schließen geht genauso: Wo ${t("f'")} über der x-Achse liegt, steigt ${t('f')}. Wo ${t("f'")} die Achse von oben nach unten kreuzt, hat ${t('f')} einen Hochpunkt. Nur die Höhe von ${t('f')} bleibt offen – der ganze Graph darf nach oben oder unten verschoben sein, die Ableitung merkt davon nichts.</p>`],
    ['Typische Fehler', `<ul><li>Die Nullstellen von ${t('f')} in die Skizze von ${t("f'")} übernommen – entscheidend sind die <b>Extremstellen</b>.</li><li>Die Höhe von ${t('f')} mit dem Wert von ${t("f'")} verwechselt: Ein Graph kann hoch liegen und trotzdem fallen.</li><li>Am Sattelpunkt einen Vorzeichenwechsel eingezeichnet: Dort berührt ${t("f'")} die x-Achse nur.</li></ul>`],
  ],
  'g-vektor': [
    ['Worum es geht', `<p>Ein Vektor beschreibt eine Verschiebung: so viel in ${t('x_1')}-, so viel in ${t('x_2')}- und so viel in ${t('x_3')}-Richtung. Er hat eine Richtung und eine Länge, aber keinen festen Ort. Der <b>Ortsvektor</b> eines Punktes ist der Pfeil vom Ursprung zu diesem Punkt.</p>`],
    ['Verbindungsvektor', `${D('\\overrightarrow{AB}=\\vec b-\\vec a')}<p>Merkregel: „Spitze minus Fuß“. Für ${t('A(1\\mid 2\\mid 3)')} und ${t('B(4\\mid 0\\mid 5)')}:</p>${D('\\overrightarrow{AB}=\\begin{pmatrix}4-1\\\\0-2\\\\5-3\\end{pmatrix}=\\begin{pmatrix}3\\\\-2\\\\2\\end{pmatrix}')}`],
    ['Rechnen mit Vektoren', `<p>Addiert wird Koordinate für Koordinate – anschaulich hängt man die Pfeile aneinander. Eine Zahl vor dem Vektor streckt ihn; eine negative Zahl dreht ihn zusätzlich um. Aus beidem zusammen entsteht eine <b>Linearkombination</b> ${t('r\\cdot\\vec a+s\\cdot\\vec b')}.</p><p>Zwei Vektoren sind <b>kollinear</b> (parallel), wenn der eine ein Vielfaches des anderen ist, etwa ${t('(2\\mid -4\\mid 6)=2\\cdot(1\\mid -2\\mid 3)')}.</p>`],
    ['Länge', `${D('|\\vec a|=\\sqrt{a_1^{\\,2}+a_2^{\\,2}+a_3^{\\,2}}')}<p>Das ist der Satz des Pythagoras im Raum. Für den Vektor oben: ${t('\\sqrt{9+4+4}=\\sqrt{17}\\approx 4{,}12')}. Das ist zugleich der Abstand der Punkte ${t('A')} und ${t('B')}.</p>`],
    ['Mittelpunkt', `${D('\\vec m=\\tfrac12\\,(\\vec a+\\vec b)')}<p>Der Mittelpunkt einer Strecke hat als Koordinaten die Mittelwerte der Endpunkte: hier ${t('M(2{,}5\\mid 1\\mid 4)')}.</p>`],
    ['Typische Fehler', `<ul><li>${t('\\vec a-\\vec b')} statt ${t('\\vec b-\\vec a')} gerechnet – der Vektor zeigt dann in die Gegenrichtung.</li><li>Beim Quadrieren das Minus mitgenommen: ${t('(-2)^2=4')}, nicht ${t('-4')}.</li><li>Punkt und Vektor verwechselt: Ein Punkt ist ein Ort, ein Vektor ein Weg.</li></ul>`],
  ],
  anwenden: [
    ['Worum es geht', `<p>Drei Aufgabentypen kommen im Abitur immer wieder: die Gleichung einer Tangente aufstellen, aus Eigenschaften eine Funktion bestimmen (Steckbrief) und mit einer ganzen Schar von Funktionen auf einmal rechnen.</p>`],
    ['Tangente', `${D("t(x)=f'(x_0)\\cdot(x-x_0)+f(x_0)")}<p>Die Tangente hat dieselbe Steigung wie der Graph und geht durch den Berührpunkt. Beispiel ${t('f(x)=x^2')} an der Stelle ${t('x_0=3')}: ${t("f'(3)=6")} und ${t('f(3)=9')}, also ${t('t(x)=6\\,(x-3)+9=6x-9')}.</p><p>Die <b>Normale</b> steht senkrecht dazu und hat die Steigung ${t("-\\tfrac{1}{f'(x_0)}")}.</p>`],
    ['Steckbrief: Text in Gleichungen übersetzen', `<ul><li>„geht durch ${t('P(1\\mid 2)')}“ heißt ${t('f(1)=2')}</li><li>„Extrempunkt bei ${t('x=2')}“ heißt ${t("f'(2)=0")}</li><li>„Wendepunkt bei ${t('x=0')}“ heißt ${t("f''(0)=0")}</li><li>„Steigung 3 bei ${t('x=1')}“ heißt ${t("f'(1)=3")}</li><li>„berührt die x-Achse bei ${t('x=2')}“ heißt ${t('f(2)=0')} und ${t("f'(2)=0")}</li></ul><p>Eine Funktion vom Grad ${t('n')} hat ${t('n+1')} unbekannte Zahlen – so viele Bedingungen braucht man.</p>`],
    ['Durchgerechnetes Beispiel', `<p>Gesucht ist eine Parabel mit Tiefpunkt ${t('T(1\\mid -2)')}, die durch ${t('P(0\\mid 1)')} geht. Ansatz: ${t('f(x)=ax^2+bx+c')}, also ${t("f'(x)=2ax+b")}.</p>${D("f(0)=1\\qquad f'(1)=0\\qquad f(1)=-2")}<p>Aus der ersten Bedingung folgt ${t('c=1')}, aus der zweiten ${t('b=-2a')}, aus der dritten ${t('a+b+1=-2')}. Einsetzen: ${t('a-2a=-3')}, also ${t('a=3')} und ${t('b=-6')}.</p>${D('f(x)=3x^2-6x+1')}<p>Probe: ${t('f(1)=3-6+1=-2')}. Passt.</p>`],
    ['Funktionenscharen', `<p>Steht in der Funktion ein Parameter ${t('k')}, rechnet man mit ihm wie mit einer festen Zahl. Die Ergebnisse hängen dann von ${t('k')} ab.</p>${D("f_k(x)=x^2-2kx\\qquad f_k'(x)=2x-2k")}<p>Die Ableitung ist null bei ${t('x=k')}; der Tiefpunkt ist ${t('T(k\\mid -k^2)')}. Alle Tiefpunkte liegen auf einer Kurve, der <b>Ortskurve</b>: Aus ${t('x=k')} und ${t('y=-k^2')} wird ${t('y=-x^2')}.</p>`],
    ['Typische Fehler', `<ul><li>Bei der Tangente ${t('f(x_0)')} vergessen oder ${t('x_0')} nicht eingesetzt.</li><li>Beim Steckbrief eine Bedingung zu wenig aufgestellt – der Punkt eines Extrempunkts liefert <b>zwei</b> Gleichungen.</li><li>Nach ${t('k')} abgeleitet statt nach ${t('x')}.</li></ul>`],
  ],
  's-kombi': [
    ['Worum es geht', `<p>Wie viele Möglichkeiten gibt es? Bei kleinen Zahlen kann man aufzählen, bei großen braucht man Zählregeln. Zwei Fragen entscheiden, welche Regel passt: Kommt es auf die <b>Reihenfolge</b> an? Darf sich etwas <b>wiederholen</b>?</p>`],
    ['Produktregel', `<p>Wird nacheinander gewählt, multiplizieren sich die Möglichkeiten: 3 Hosen und 4 Hemden ergeben ${t('3\\cdot 4=12')} Kombinationen. Darauf bauen alle weiteren Formeln auf.</p>`],
    ['Mit Reihenfolge', `${D('n^k\\qquad \\frac{n!}{(n-k)!}\\qquad n!')}<p><b>Mit Wiederholung:</b> Eine vierstellige PIN hat ${t('10^4=10\\,000')} Möglichkeiten. <b>Ohne Wiederholung:</b> Gold, Silber und Bronze unter 8 Läufern lassen sich auf ${t('8\\cdot 7\\cdot 6=336')} Arten vergeben. <b>Alle anordnen:</b> 5 Bücher im Regal stehen auf ${t('5!=120')} Arten.</p>`],
    ['Ohne Reihenfolge', `${D('\\binom{n}{k}=\\frac{n!}{k!\\,(n-k)!}')}<p>Der Binomialkoeffizient zählt, auf wie viele Arten man ${t('k')} aus ${t('n')} auswählen kann, wenn nur zählt, <b>wer</b> dabei ist. Beispiel: ${t('\\binom 52=\\tfrac{5\\cdot 4}{2}=10')}. Beim Lotto „6 aus 49“ sind es 13 983 816 Möglichkeiten.</p><p>Praktisch: ${t('\\binom nk=\\binom n{n-k}')} – 3 aus 10 auswählen ist dasselbe wie 7 aussortieren.</p>`],
    ['Von der Anzahl zur Wahrscheinlichkeit', `<p>Sind alle Möglichkeiten gleich wahrscheinlich, teilt man die günstigen durch alle möglichen. Sechs Richtige im Lotto haben deshalb die Wahrscheinlichkeit 1 zu 13 983 816.</p>`],
    ['Typische Fehler', `<ul><li>Reihenfolge mitgezählt, obwohl sie egal ist (oder umgekehrt).</li><li>Addiert statt multipliziert: „und dann“ heißt mal, „oder“ heißt plus.</li><li>${t('0!=1')} vergessen.</li></ul>`],
  ],
  'a-grund': [
    ['Worum es geht', `<p>Die meisten Punkte gehen im Abitur nicht bei den neuen Themen verloren, sondern beim Umformen: ein Vorzeichen, eine Klammer, ein Bruch. Dieses Kapitel sammelt das Handwerkszeug, auf dem alles andere aufbaut.</p>`],
    ['Brüche und Klammern', `<p>Brüche addiert man erst nach dem Gleichnamigmachen. Multipliziert wird Zähler mal Zähler und Nenner mal Nenner, dividiert wird mit dem Kehrwert. Ein Minus vor einer Klammer dreht <b>jedes</b> Vorzeichen in der Klammer um.</p>${D('(a\\pm b)^2=a^2\\pm 2ab+b^2\\qquad (a+b)(a-b)=a^2-b^2')}`],
    ['Potenzgesetze', `${D('x^a\\cdot x^b=x^{a+b}\\qquad (x^a)^b=x^{a\\cdot b}\\qquad x^{-n}=\\frac{1}{x^n}')}<p>Dazu kommt ${t('x^{1/n}=\\sqrt[n]{x}')}. Mit diesen Regeln lassen sich Wurzeln und Brüche als Potenzen schreiben – das braucht man später zum Ableiten.</p>`],
    ['Lineare Gleichungen', `<p>Alle Glieder mit ${t('x')} auf eine Seite, alle Zahlen auf die andere, dann teilen.</p>${D('3x+4=x-6\\qquad 2x=-10\\qquad x=-5')}`],
    ['Quadratische Gleichungen', `${D('x^2+px+q=0\\qquad x_{1,2}=-\\frac p2\\pm\\sqrt{\\Bigl(\\frac p2\\Bigr)^2-q}')}<p>Beispiel ${t('x^2-4x-5=0')}: ${t('p=-4')}, ${t('q=-5')}, also ${t('x=2\\pm\\sqrt{4+5}=2\\pm 3')}. Lösungen: ${t('5')} und ${t('-1')}. Steht unter der Wurzel eine negative Zahl, gibt es keine Lösung.</p><p>Fehlt die Zahl ohne ${t('x')}, geht es schneller durch Ausklammern: ${t('x^2-3x=0')} wird zu ${t('x\\,(x-3)=0')}, also ${t('x=0')} oder ${t('x=3')}.</p>`],
    ['Typische Fehler', `<ul><li>${t('(a+b)^2=a^2+b^2')} geschrieben – das gemischte Glied ${t('2ab')} fehlt.</li><li>Durch ${t('x')} geteilt und dabei die Lösung ${t('x=0')} verloren.</li><li>In der pq-Formel das Vorzeichen von ${t('p')} nicht umgedreht.</li><li>Die Gleichung vor der pq-Formel nicht durch die Zahl vor ${t('x^2')} geteilt.</li></ul>`],
  ],
  's-grund': [
    ['Worum es geht', `<p>Prozente, Häufigkeiten und einfache Wahrscheinlichkeiten sind die Sprache der Stochastik. Wer hier sicher ist, versteht später Baumdiagramme und Verteilungen ohne Mühe.</p>`],
    ['Prozent', `${D('W=G\\cdot\\frac{p}{100}')}<p>15 % von 80 sind ${t('80\\cdot 0{,}15=12')}. Wächst etwas um 20 %, multipliziert man mit ${t('1{,}2')}; sinkt es um 20 %, mit ${t('0{,}8')}. Achtung: Erst 20 % mehr und dann 20 % weniger ergibt nicht den alten Wert, sondern ${t('1{,}2\\cdot 0{,}8=0{,}96')}.</p>`],
    ['Häufigkeit und Wahrscheinlichkeit', `<p>Die <b>absolute</b> Häufigkeit zählt, wie oft etwas vorkam; die <b>relative</b> teilt durch die Gesamtzahl. Wiederholt man einen Versuch sehr oft, pendelt sich die relative Häufigkeit bei der Wahrscheinlichkeit ein (Gesetz der großen Zahlen).</p>`],
    ['Laplace und Gegenereignis', `${D('P(E)=\\frac{\\text{günstige}}{\\text{mögliche}}\\qquad P(\\overline E)=1-P(E)')}<p>Die erste Formel gilt nur, wenn alle Ergebnisse gleich wahrscheinlich sind – wie beim Würfel. Die zweite spart oft viel Arbeit: „Mindestens eine Sechs bei zwei Würfen“ ist das Gegenteil von „keine Sechs“, also ${t('1-\\bigl(\\tfrac56\\bigr)^2=\\tfrac{11}{36}\\approx 0{,}31')}.</p>`],
    ['Vierfeldertafel', `<p>Zwei Merkmale mit je zwei Ausprägungen passen in eine Tabelle mit vier Feldern. Innen stehen die Kombinationen („und“), am Rand die Summen. Weil jede Zeile und jede Spalte aufgehen muss, reichen wenige Angaben, um den Rest auszufüllen.</p>`],
    ['Typische Fehler', `<ul><li>Prozent vom falschen Grundwert gerechnet.</li><li>Die Laplace-Formel benutzt, obwohl die Ergebnisse nicht gleich wahrscheinlich sind.</li><li>In der Vierfeldertafel „A und B“ mit „A unter der Bedingung B“ verwechselt.</li></ul>`],
  ],
  'g-grund': [
    ['Worum es geht', `<p>Rechtwinklige Dreiecke stecken überall: in Dachschrägen, Rampen, Diagonalen und in jedem Abstand im Koordinatensystem. Zusammen mit den Formeln für Flächen und Körper sind sie die Grundlage der ganzen Geometrie.</p>`],
    ['Satz des Pythagoras', `${D('a^2+b^2=c^2')}<p>Er gilt nur im rechtwinkligen Dreieck. ${t('c')} ist die Hypotenuse – die längste Seite, gegenüber dem rechten Winkel. Beispiel: Katheten 3 und 4 ergeben ${t('c=\\sqrt{9+16}=5')}.</p>`],
    ['Sinus, Kosinus, Tangens', `${D('\\sin\\alpha=\\frac{\\text{Gegenkathete}}{\\text{Hypotenuse}}\\qquad\\cos\\alpha=\\frac{\\text{Ankathete}}{\\text{Hypotenuse}}\\qquad\\tan\\alpha=\\frac{\\text{Gegenkathete}}{\\text{Ankathete}}')}<p>Die Gegenkathete liegt dem Winkel gegenüber, die Ankathete liegt an ihm an. Beispiel: Eine 5 m lange Leiter lehnt im Winkel von 60° zum Boden an der Wand. Sie reicht ${t('5\\cdot\\sin 60^\\circ\\approx 4{,}33')} m hoch.</p>`],
    ['Flächen und Körper', `${D('A_{\\triangle}=\\tfrac12\\,g\\,h\\qquad A_{\\circ}=\\pi r^2')}<p>Prisma und Zylinder: Grundfläche mal Höhe. Pyramide und Kegel: ein Drittel davon. Kugel: ${t('V=\\tfrac43\\pi r^3')}.</p>`],
    ['Mittelpunkt und Abstand', `<p>Der Mittelpunkt zweier Punkte hat als Koordinaten die Mittelwerte. Der Abstand ist die Hypotenuse eines rechtwinkligen Dreiecks aus den Koordinaten-Unterschieden – also wieder Pythagoras.</p>${D('M\\Bigl(\\frac{a_1+b_1}{2}\\Bigm|\\frac{a_2+b_2}{2}\\Bigr)')}`],
    ['Typische Fehler', `<ul><li>Die Hypotenuse falsch erkannt – sie liegt immer gegenüber dem rechten Winkel.</li><li>Taschenrechner auf Bogenmaß statt auf Grad.</li><li>Bei Pyramide und Kegel das Drittel vergessen.</li><li>Durchmesser statt Radius eingesetzt.</li></ul>`],
  ],
  'a-gebrochen': [
    ['Worum es geht', `<p>Eine gebrochen-rationale Funktion ist ein Bruch aus zwei ganzrationalen Funktionen. Spannend wird sie dort, wo der Nenner null wird: Der Graph reißt ab und schießt nach oben oder unten weg.</p>`],
    ['Definitionslücken und Polstellen', `<p>Überall, wo der Nenner null ist, ist die Funktion nicht definiert. Ist der Zähler dort <b>nicht</b> null, liegt eine <b>Polstelle</b> vor – der Graph schmiegt sich an eine senkrechte Asymptote. Sind Zähler und Nenner beide null und lässt sich kürzen, ist es nur ein Loch im Graphen (hebbare Lücke).</p>`],
    ['Nullstellen und Verhalten im Unendlichen', `<p>Ein Bruch ist null, wenn der <b>Zähler</b> null ist (und der Nenner nicht). Für sehr große ${t('x')} entscheidet der Vergleich der Grade:</p><ul><li>Zählergrad kleiner: Der Graph nähert sich der x-Achse.</li><li>Grade gleich: Er nähert sich der Waagerechten mit dem Quotienten der beiden höchsten Vorzahlen.</li><li>Zählergrad um eins größer: Es gibt eine schräge Asymptote.</li></ul>`],
    ['Quotientenregel', `${D("\\Bigl(\\frac uv\\Bigr)'=\\frac{u'\\,v-u\\,v'}{v^2}")}<p>Merkhilfe: „Nenner mal Ableitung Zähler minus Zähler mal Ableitung Nenner, durch Nenner im Quadrat“. Wegen des Minuszeichens kommt es auf die Reihenfolge an.</p>`],
    ['Durchgerechnetes Beispiel', `${D('f(x)=\\frac{2x+1}{x-3}')}<p>Polstelle bei ${t('x=3')}, Nullstelle bei ${t('x=-0{,}5')}. Die Grade sind gleich, also waagerechte Asymptote ${t('y=\\tfrac 21=2')}.</p>${D("f'(x)=\\frac{2\\,(x-3)-(2x+1)\\cdot 1}{(x-3)^2}=\\frac{-7}{(x-3)^2}")}<p>Die Ableitung ist überall negativ: Der Graph fällt auf beiden Seiten der Polstelle. Extrempunkte gibt es keine.</p>`],
    ['Typische Fehler', `<ul><li>Nullstellen des Nenners als Nullstellen der Funktion angegeben.</li><li>In der Quotientenregel die beiden Produkte vertauscht – das Vorzeichen stimmt dann nicht.</li><li>Den Nenner ausmultipliziert statt ${t('(x-3)^2')} stehen zu lassen.</li></ul>`],
  ],
  'a-trig': [
    ['Worum es geht', `<p>Sinus und Kosinus beschreiben alles, was sich wiederholt: Gezeiten, Tageslänge, Schwingungen, Wechselstrom. In der Analysis rechnet man dabei immer im <b>Bogenmaß</b>: ${t('180^\\circ')} entsprechen ${t('\\pi')}.</p>`],
    ['Ableiten', `${D("(\\sin x)'=\\cos x\\qquad(\\cos x)'=-\\sin x")}<p>Viermal ableiten führt im Kreis: Sinus, Kosinus, minus Sinus, minus Kosinus, Sinus. Steht im Argument mehr als ${t('x')}, greift die Kettenregel:</p>${D("\\bigl(\\sin(b\\,x)\\bigr)'=b\\cdot\\cos(b\\,x)")}`],
    ['Integrieren', `${D('\\int\\sin x\\,dx=-\\cos x+C\\qquad\\int\\cos x\\,dx=\\sin x+C')}<p>Beim Aufleiten wandert das Minus zum Sinus. Ein Faktor im Argument wird zum Teiler: ${t('\\int\\sin(b\\,x)\\,dx=-\\tfrac 1b\\cos(b\\,x)+C')}.</p>`],
    ['Durchgerechnetes Beispiel', `${D("f(x)=3\\sin(2x)\\qquad f'(x)=6\\cos(2x)")}<p>Die Periode ist ${t('\\tfrac{2\\pi}{2}=\\pi')}. Extremstellen liegen dort, wo ${t('\\cos(2x)=0')} ist, zum ersten Mal bei ${t('x=\\tfrac{\\pi}{4}')}. Fläche unter dem ersten Bogen:</p>${D('\\int_0^{\\pi/2}3\\sin(2x)\\,dx=\\Bigl[-1{,}5\\cos(2x)\\Bigr]_0^{\\pi/2}=3')}<p>Eingesetzt: ${t('-1{,}5\\cdot(-1)-(-1{,}5\\cdot 1)=1{,}5+1{,}5')}.</p>`],
    ['Typische Fehler', `<ul><li>Das Minus an der falschen Stelle: Es gehört zur Ableitung des Kosinus und zur Stammfunktion des Sinus.</li><li>Die innere Ableitung vergessen – oder beim Integrieren mit ${t('b')} multipliziert statt geteilt.</li><li>Taschenrechner im Gradmaß gelassen.</li></ul>`],
  ],
  'a-rotation': [
    ['Worum es geht', `<p>Dreht sich ein Graph um die x-Achse, entsteht ein Körper – eine Vase, ein Trichter, ein Fass. Sein Volumen liefert ein Integral. Im zweiten Teil geht es um Flächen, die unendlich weit reichen und trotzdem einen endlichen Inhalt haben können.</p>`],
    ['Rotationsvolumen', `${D('V=\\pi\\int_a^b\\bigl(f(x)\\bigr)^2\\,dx')}<p>Die Idee: Der Körper wird in dünne Scheiben geschnitten. Jede Scheibe ist ein Kreis mit Radius ${t('f(x)')}, also mit Fläche ${t('\\pi f(x)^2')}. Das Integral summiert alle Scheiben auf.</p>`],
    ['Durchgerechnetes Beispiel', `<p>${t('f(x)=\\sqrt x')} dreht sich über ${t('[0;\\,4]')} um die x-Achse.</p>${D('V=\\pi\\int_0^4 x\\,dx=\\pi\\Bigl[\\tfrac12x^2\\Bigr]_0^4=8\\pi\\approx 25{,}13')}<p>Zur Kontrolle der Formel: Die Gerade ${t('f(x)=\\tfrac rh\\,x')} über ${t('[0;\\,h]')} erzeugt einen Kegel, und das Integral liefert genau ${t('\\tfrac13\\pi r^2h')}.</p>`],
    ['Flächen ins Unendliche', `${D('\\int_1^{\\infty}f(x)\\,dx=\\lim_{b\\to\\infty}\\int_1^{b}f(x)\\,dx')}<p>Man rechnet erst bis zu einer Grenze ${t('b')} und lässt ${t('b')} dann wachsen.</p>${D('\\int_1^{b}\\frac{1}{x^2}\\,dx=\\Bigl[-\\frac 1x\\Bigr]_1^{b}=1-\\frac 1b')}<p>Für ${t('b\\to\\infty')} strebt das gegen ${t('1')}: Die Fläche ist endlich. Bei ${t('\\tfrac 1x')} kommt dagegen ${t('\\ln b')} heraus, und das wächst über jede Grenze – diese Fläche ist unendlich groß.</p>`],
    ['Typische Fehler', `<ul><li>Erst integriert und dann quadriert – richtig ist: erst ${t('f(x)')} quadrieren, dann integrieren.</li><li>Den Faktor ${t('\\pi')} vergessen.</li><li>„Unendlich eingesetzt“ statt den Grenzwert zu bilden.</li></ul>`],
  ],
  's-zufall': [
    ['Worum es geht', `<p>Eine Zufallsgröße macht aus dem Ergebnis eines Zufallsversuchs eine Zahl – einen Gewinn, eine Anzahl, eine Punktzahl. Mit Erwartungswert und Standardabweichung lässt sich ein ganzes Glücksspiel in zwei Zahlen zusammenfassen.</p>`],
    ['Erwartungswert', `${D('\\mu=x_1\\,p_1+x_2\\,p_2+\\dots+x_n\\,p_n')}<p>Jeder Wert wird mit seiner Wahrscheinlichkeit gewichtet. Das Ergebnis ist der Durchschnitt, der sich auf lange Sicht einstellt. Ein Spiel heißt <b>fair</b>, wenn der erwartete Gewinn null ist.</p><p>Beispiel: Einsatz 2 €, bei einer Sechs gibt es 9 € zurück. Der Gewinn ist ${t('7')} mit Wahrscheinlichkeit ${t('\\tfrac16')} und ${t('-2')} mit ${t('\\tfrac56')}: ${t('\\mu=\\tfrac76-\\tfrac{10}{6}=-0{,}5')}. Auf Dauer verliert man 50 Cent pro Spiel.</p>`],
    ['Varianz und Standardabweichung', `${D('V(X)=\\sum (x_i-\\mu)^2\\,p_i\\qquad\\sigma=\\sqrt{V(X)}')}<p>Die Varianz misst, wie weit die Werte im Mittel vom Erwartungswert entfernt liegen (im Quadrat). Im Beispiel: ${t('7{,}5^2\\cdot\\tfrac16+(-1{,}5)^2\\cdot\\tfrac56=11{,}25')}, also ${t('\\sigma\\approx 3{,}35')} €.</p>`],
    ['Unabhängigkeit', `${D('P(A\\cap B)=P(A)\\cdot P(B)')}<p>Zwei Ereignisse sind unabhängig, wenn das Eintreten des einen die Wahrscheinlichkeit des anderen nicht verändert. Geprüft wird durch Nachrechnen: Stimmt die Gleichung, sind sie unabhängig – sonst nicht. Ein Gefühl reicht hier nicht.</p>`],
    ['Ziehen ohne Zurücklegen', `${D('P(X=k)=\\frac{\\binom Mk\\cdot\\binom{N-M}{n-k}}{\\binom Nn}')}<p>Aus ${t('N')} Kugeln, von denen ${t('M')} markiert sind, werden ${t('n')} gezogen. Beispiel: 10 Kugeln, 4 rote, 3 Züge. Genau 2 rote:</p>${D('\\frac{\\binom42\\cdot\\binom61}{\\binom{10}{3}}=\\frac{6\\cdot 6}{120}=0{,}3')}`],
    ['Typische Fehler', `<ul><li>Beim Gewinn den Einsatz nicht abgezogen.</li><li>Varianz und Standardabweichung verwechselt – erst die Wurzel hat wieder die Einheit der Werte.</li><li>Die Binomialverteilung benutzt, obwohl ohne Zurücklegen aus einer kleinen Menge gezogen wird.</li></ul>`],
  ],
  'g-kugel': [
    ['Worum es geht', `<p>Eine Kugel besteht aus allen Punkten, die von einem Mittelpunkt gleich weit entfernt sind. Mit ihr lassen sich Reichweiten, Sicherheitszonen und Funkbereiche beschreiben – und fast immer geht es um Abstände.</p>`],
    ['Kugelgleichung', `${D('(x_1-m_1)^2+(x_2-m_2)^2+(x_3-m_3)^2=r^2')}<p>Links steht das Quadrat des Abstands vom Mittelpunkt ${t('M')}. Ein Punkt liegt <b>auf</b> der Kugel, wenn sein Abstand genau ${t('r')} ist, <b>innen</b> bei kleinerem, <b>außen</b> bei größerem Abstand.</p><p>Beispiel: ${t('M(1\\mid 2\\mid 0)')}, ${t('r=3')}, ${t('P(3\\mid 4\\mid 1)')}. Abstand: ${t('\\sqrt{4+4+1}=3')} – der Punkt liegt auf der Kugel.</p>`],
    ['Kugel und Ebene', `<p>Entscheidend ist der Abstand ${t('d')} des Mittelpunkts von der Ebene. Ist ${t('d>r')}, gibt es keinen gemeinsamen Punkt. Bei ${t('d=r')} berührt die Ebene die Kugel (Tangentialebene). Bei ${t('d<r')} schneidet sie einen Kreis aus:</p>${D('r_{\\text{Kreis}}=\\sqrt{r^2-d^2}')}`],
    ['Abstand Punkt – Gerade', `<p>Gesucht ist der Punkt ${t('F')} auf der Geraden, für den die Verbindung zu ${t('P')} senkrecht auf der Geraden steht: ${t('\\overrightarrow{PF}\\cdot\\vec u=0')}.</p>${D('g:\\ \\vec x=\\begin{pmatrix}1\\\\0\\\\2\\end{pmatrix}+t\\begin{pmatrix}1\\\\2\\\\2\\end{pmatrix}\\qquad P(4\\mid 3\\mid 2)')}<p>Mit ${t('F(1+t\\mid 2t\\mid 2+2t)')} ist ${t('\\overrightarrow{PF}=(t-3\\mid 2t-3\\mid 2t)')}. Skalarprodukt mit dem Richtungsvektor: ${t('(t-3)+2(2t-3)+2\\cdot 2t=9t-9=0')}, also ${t('t=1')}.</p><p>Lotfußpunkt ${t('F(2\\mid 2\\mid 4)')}, Abstand ${t('|(-2\\mid -1\\mid 2)|=3')}.</p>`],
    ['Lage zweier Ebenen', `<p>Sind die Normalenvektoren Vielfache voneinander, sind die Ebenen parallel – oder sogar gleich; das zeigt die Punktprobe. Andernfalls schneiden sie sich in einer Geraden.</p>`],
    ['Typische Fehler', `<ul><li>In der Kugelgleichung die Vorzeichen des Mittelpunkts vertauscht: ${t('(x_1+2)^2')} gehört zu ${t('m_1=-2')}.</li><li>Rechts ${t('r')} statt ${t('r^2')} geschrieben.</li><li>Beim Abstand zur Geraden irgendeinen Punkt der Geraden genommen statt den Lotfußpunkt.</li></ul>`],
  ],
  'a-wachstum': [
    ['Worum es geht', `<p>Exponentielles Wachstum geht theoretisch ewig weiter. In der Wirklichkeit gibt es fast immer eine Grenze: Der Akku ist irgendwann voll, der Tee hat Raumtemperatur, alle kennen das Gerücht. Zwei Modelle beschreiben das.</p>`],
    ['Begrenztes Wachstum', `${D('f(t)=S-a\\cdot e^{-k\\,t}')}<p>${t('S')} ist die Grenze (Schranke). Am Anfang ist der Bestand ${t('f(0)=S-a')}. Der Abstand zur Grenze schrumpft exponentiell – der Bestand wächst also am Anfang am schnellsten und dann immer langsamer.</p>${D("f'(t)=k\\cdot\\bigl(S-f(t)\\bigr)")}<p>In Worten: Die Änderung ist proportional zu dem, was bis zur Grenze noch <b>fehlt</b>.</p>`],
    ['Durchgerechnetes Beispiel', `<p>Ein Tee kühlt in einem 20 °C warmen Raum ab: ${t('f(t)=20+60\\,e^{-0{,}1t}')} (${t('t')} in Minuten). Das ist dieselbe Bauart mit ${t('a=-60')}: Der Tee kommt von oben an die Grenze.</p><p>Start: ${t('f(0)=80')} °C. Nach 10 Minuten: ${t('20+60\\,e^{-1}\\approx 42{,}1')} °C. Wann sind es 30 °C? ${t('60\\,e^{-0{,}1t}=10')}, also ${t('t=\\tfrac{\\ln 6}{0{,}1}\\approx 17{,}9')} Minuten.</p>`],
    ['Logistisches Wachstum', `${D('f(t)=\\frac{S}{1+a\\cdot e^{-k\\,t}}')}<p>Eine S-Kurve: Am Anfang wächst es fast exponentiell (es sind wenige da, aber noch viel Platz), am Ende bremst die Grenze. Am schnellsten wächst der Bestand genau bei der <b>halben Grenze</b> – dort liegt der Wendepunkt.</p>${D('f(t_W)=\\frac S2\\qquad t_W=\\frac{\\ln a}{k}')}<p>Beispiel: ${t('S=1000')}, ${t('a=9')}, ${t('k=0{,}5')}. Start ${t('f(0)=100')}; stärkstes Wachstum bei ${t('t_W=\\tfrac{\\ln 9}{0{,}5}\\approx 4{,}4')}, dort sind es 500.</p>`],
    ['Welches Modell passt?', `<ul><li><b>Exponentiell:</b> keine Grenze, wird immer schneller.</li><li><b>Begrenzt:</b> am Anfang am schnellsten, dann immer langsamer.</li><li><b>Logistisch:</b> erst langsam, dann schnell, dann wieder langsam.</li></ul>`],
    ['Typische Fehler', `<ul><li>Anfangswert mit ${t('S')} oder mit ${t('a')} verwechselt – es ist ${t('S-a')}.</li><li>Beim Auflösen nach ${t('t')} das Minus im Exponenten verloren.</li><li>Den Wendepunkt beim begrenzten Wachstum gesucht: Dort gibt es keinen.</li></ul>`],
  ],
  'g-ebene2': [
    ['Worum es geht', `<p>Eine Ebene lässt sich auf drei Arten aufschreiben. Jede Form hat ihre Stärke: Die Parameterform entsteht direkt aus drei Punkten, die Koordinatenform ist am besten zum Rechnen, und an den Spurpunkten sieht man sofort, wie die Ebene im Raum liegt.</p>`],
    ['Parameterform', `${D('E:\\ \\vec x=\\vec p+r\\cdot\\vec u+s\\cdot\\vec v')}<p>Vom Stützpunkt aus erreicht man jeden Punkt der Ebene, indem man ein Stück in Richtung ${t('\\vec u')} und ein Stück in Richtung ${t('\\vec v')} geht. Aus drei Punkten: ${t('\\vec p=\\vec a')}, ${t('\\vec u=\\overrightarrow{AB}')}, ${t('\\vec v=\\overrightarrow{AC}')}. Die beiden Spannvektoren dürfen nicht parallel sein.</p>`],
    ['Normalenvektor und Normalenform', `<p>Ein Normalenvektor ${t('\\vec n')} steht senkrecht auf der Ebene, also auf beiden Spannvektoren: ${t('\\vec n\\cdot\\vec u=0')} und ${t('\\vec n\\cdot\\vec v=0')}. Am schnellsten liefert ihn das Kreuzprodukt ${t('\\vec u\\times\\vec v')}.</p>${D('E:\\ (\\vec x-\\vec p)\\cdot\\vec n=0')}<p>Ausmultipliziert wird daraus die Koordinatenform ${t('n_1x_1+n_2x_2+n_3x_3=d')} mit ${t('d=\\vec n\\cdot\\vec p')}.</p>`],
    ['Durchgerechnetes Beispiel', `<p>${t('A(1\\mid 0\\mid 0)')}, ${t('B(0\\mid 2\\mid 0)')}, ${t('C(0\\mid 0\\mid 3)')}. Spannvektoren: ${t('\\vec u=(-1\\mid 2\\mid 0)')} und ${t('\\vec v=(-1\\mid 0\\mid 3)')}.</p>${D('\\vec n=\\vec u\\times\\vec v=\\begin{pmatrix}2\\cdot 3-0\\cdot 0\\\\0\\cdot(-1)-(-1)\\cdot 3\\\\(-1)\\cdot 0-2\\cdot(-1)\\end{pmatrix}=\\begin{pmatrix}6\\\\3\\\\2\\end{pmatrix}')}<p>${t('d=\\vec n\\cdot\\vec a=6')}, also:</p>${D('E:\\ 6x_1+3x_2+2x_3=6')}<p>Probe mit ${t('B')}: ${t('3\\cdot 2=6')}. Mit ${t('C')}: ${t('2\\cdot 3=6')}. Passt.</p>`],
    ['Spurpunkte', `<p>Die Spurpunkte sind die Schnittpunkte mit den Koordinatenachsen. Auf der ${t('x_1')}-Achse sind ${t('x_2')} und ${t('x_3')} null – es bleibt ${t('6x_1=6')}, also ${t('S_1(1\\mid 0\\mid 0)')}. Genauso ${t('S_2(0\\mid 2\\mid 0)')} und ${t('S_3(0\\mid 0\\mid 3)')}. Verbindet man die drei, erhält man das Spurdreieck, mit dem sich die Ebene zeichnen lässt.</p><p>Fehlt in der Gleichung eine Koordinate, gibt es auf dieser Achse keinen Spurpunkt: Die Ebene läuft parallel zu ihr.</p>`],
    ['Typische Fehler', `<ul><li>Beim Kreuzprodukt in der mittleren Zeile das Vorzeichen vertauscht.</li><li>${t('d')} vergessen und „= 0“ geschrieben.</li><li>Für den Spurpunkt nur eine statt zwei Koordinaten null gesetzt.</li></ul>`],
  ],
  'a-umkehr': [
    ['Worum es geht', `<p>Eine Funktion ordnet jedem ${t('x')} ein ${t('y')} zu. Die Umkehrfunktion beantwortet die Gegenfrage: Welches ${t('x')} gehört zu einem gegebenen ${t('y')}? Wer eine Formel „nach der anderen Größe auflöst“, bildet genau diese Umkehrfunktion. Die wichtigsten Paare sind Quadrat und Wurzel sowie e-Funktion und Logarithmus.</p>`],
    ['Umkehrfunktion bestimmen', `<p>In drei Schritten: ${t('y=f(x)')} schreiben, nach ${t('x')} auflösen, ${t('x')} und ${t('y')} vertauschen.</p>${D('y=2x+6\\ \\Rightarrow\\ x=\\dfrac{y-6}{2}\\ \\Rightarrow\\ f^{-1}(x)=\\dfrac{x-6}{2}')}<p>Der Graph der Umkehrfunktion entsteht durch Spiegeln an der Winkelhalbierenden ${t('y=x')}. Definitions- und Wertemenge tauschen die Rollen.</p>`],
    ['Wann eine Funktion umkehrbar ist', `<p>Umkehrbar ist ${t('f')} nur, wenn jeder Funktionswert genau einmal vorkommt – das ist bei streng monotonen Funktionen der Fall. Die Normalparabel ist es nicht: ${t('2^2=(-2)^2')}. Beschränkt man sie auf ${t('x\\ge 0')}, wird sie umkehrbar, und die Umkehrung ist ${t('\\sqrt x')}.</p>`],
    ['Wurzelfunktion und ihr Definitionsbereich', `${D('f(x)=\\sqrt{x-3}\\quad\\text{ist definiert für}\\quad x\\ge 3')}<p>Unter einer Quadratwurzel darf nichts Negatives stehen. Man setzt den Ausdruck unter der Wurzel größer oder gleich null und löst die Ungleichung. Achtung: Beim Teilen durch eine negative Zahl dreht sich das Zeichen um.</p>`],
    ['Durchgerechnetes Beispiel: Wurzel ableiten', `<p>Gesucht ist die Tangente an ${t('f(x)=\\sqrt x')} bei ${t('x=4')}.</p>${D("f(x)=x^{1/2}\\ \\Rightarrow\\ f'(x)=\\tfrac12x^{-1/2}=\\dfrac{1}{2\\sqrt x}")}<p>Steigung: ${t("f'(4)=\\tfrac14")}. Berührpunkt: ${t('(4\\mid 2)')}. Tangente: ${t('y=\\tfrac14(x-4)+2=\\tfrac14x+1')}.</p>`],
    ['Typische Fehler', `<ul><li>Den Kehrwert ${t('\\tfrac{1}{f(x)}')} mit der Umkehrfunktion ${t('f^{-1}(x)')} verwechselt.</li><li>Beim Ableiten der Wurzel den Faktor ${t('\\tfrac12')} vergessen.</li><li>Bei ${t('\\sqrt{3x+1}')} die innere Ableitung 3 vergessen (Kettenregel).</li><li>Den Definitionsbereich der Umkehrfunktion nicht angegeben.</li></ul>`],
  ],
  'a-numerik': [
    ['Worum es geht', `<p>Drei Werkzeuge, die in Prüfungsaufgaben immer wieder auftauchen: Die Integralfunktion macht aus einem Integral eine Funktion, das Newton-Verfahren findet Nullstellen, die sich nicht exakt ausrechnen lassen, und die Ortskurve zeigt, wo die besonderen Punkte einer ganzen Kurvenschar liegen.</p>`],
    ['Integralfunktion', `${D("J_a(x)=\\displaystyle\\int_a^x f(t)\\,dt")}<p>Die untere Grenze ${t('a')} ist fest, die obere läuft. Nach dem Hauptsatz gilt ${t("J_a'(x)=f(x)")}: Die Integralfunktion ist eine Stammfunktion von ${t('f')} – und zwar die, die bei ${t('x=a')} den Wert 0 hat. Ohne Integralzeichen: ${t('J_a(x)=F(x)-F(a)')}.</p>`],
    ['Newton-Verfahren', `${D("x_{n+1}=x_n-\\dfrac{f(x_n)}{f'(x_n)}")}<p>Idee: An der Stelle ${t('x_n')} wird die Kurve durch ihre Tangente ersetzt. Deren Nullstelle ist der nächste Näherungswert. Liegt der Startwert nah genug an der Nullstelle, verdoppelt sich mit jedem Schritt etwa die Zahl der richtigen Stellen.</p>`],
    ['Durchgerechnetes Beispiel: Wurzel aus 2', `<p>Gesucht ist die positive Nullstelle von ${t('f(x)=x^2-2')}, Startwert ${t('x_0=2')}.</p>${D('x_1=2-\\dfrac{2}{4}=1{,}5\\qquad x_2=1{,}5-\\dfrac{0{,}25}{3}\\approx 1{,}4167')}<p>Schon nach zwei Schritten stimmen zwei Nachkommastellen: ${t('\\sqrt 2\\approx 1{,}4142')}.</p>`],
    ['Ortskurve', `<p>Für die Schar ${t('f_k(x)=x^2-2kx+3')} liegt der Scheitel bei ${t('x=k')} mit ${t('y=-k^2+3')}. Löst man die x-Koordinate nach ${t('k')} auf und setzt in die y-Koordinate ein, verschwindet der Parameter:</p>${D('y=-x^2+3')}<p>Auf dieser Parabel liegen alle Scheitelpunkte der Schar.</p>`],
    ['Typische Fehler', `<ul><li>Beim Newton-Verfahren ${t("f'")} und ${t('f')} im Bruch vertauscht oder addiert statt abgezogen.</li><li>Bei der Integralfunktion ${t('F(a)')} nicht abgezogen.</li><li>Bei der Ortskurve ${t('k')} nicht vollständig ersetzt.</li></ul>`],
  ],
  's-test2': [
    ['Worum es geht', `<p>Dieses Kapitel sammelt vier Themen, die das Bild der Stochastik abrunden: Ereignisse sauber als Mengen schreiben, Histogramme lesen, Fragen rückwärts stellen („wie oft muss ich es mindestens versuchen?“) und Hypothesen zweiseitig testen. Dazu kommt der Blick auf stetige Zufallsgrößen, bei denen Wahrscheinlichkeiten Flächen sind.</p>`],
    ['Ereignisse als Mengen', `${D('P(A\\cup B)=P(A)+P(B)-P(A\\cap B)')}<p>${t('A\\cap B')} heißt „A und B“, ${t('A\\cup B')} „A oder B“, ${t('\\overline A')} „nicht A“. Für das Gegenteil von „A oder B“ gilt ${t('\\overline{A\\cup B}=\\overline A\\cap\\overline B')}: weder A noch B.</p>`],
    ['Binomialverteilung: einzeln und kumuliert', `${D('P(X=k)=\\binom{n}{k}\\cdot p^k\\cdot(1-p)^{n-k}')}<p>Das ist die <b>Einzelwahrscheinlichkeit</b> für genau ${t('k')} Treffer. Die <b>kumulierte</b> Wahrscheinlichkeit summiert alle Einzelwahrscheinlichkeiten bis ${t('k')} auf: ${t('P(X\\le k)=P(X=0)+\\dots+P(X=k)')}. Aus den Tabellenwerten für „höchstens“ ergibt sich alles andere:</p>${D('P(X\\ge k)=1-P(X\\le k-1)\\qquad P(a\\le X\\le b)=P(X\\le b)-P(X\\le a-1)')}<p>Auch die Einzelwahrscheinlichkeit steckt in der Tabelle: ${t('P(X=k)=P(X\\le k)-P(X\\le k-1)')}.</p>`],
    ['Histogramm einer Binomialverteilung', `${D('\\mu=n\\cdot p\\qquad\\sigma=\\sqrt{n\\cdot p\\cdot(1-p)}')}<p>Jede Säule hat die Breite 1 und als Höhe die Wahrscheinlichkeit für genau diese Trefferzahl. Die höchste Säule steht beim Erwartungswert. Für ${t('p<0{,}5')} liegt der Gipfel links, für ${t('p>0{,}5')} rechts. Mit wachsendem ${t('n')} wird das Bild breiter und flacher.</p>`],
    ['Durchgerechnetes Beispiel: zweiseitiger Test', `<p>Behauptung: Eine Münze ist fair, ${t('H_0:\\ p=0{,}5')}. Sie wird 100-mal geworfen, getestet wird auf dem 5-%-Niveau.</p>${D('\\mu=50\\qquad\\sigma=5\\qquad 1{,}96\\cdot\\sigma=9{,}8')}<p>Annahmebereich: ${t('[41;\\ 59]')}. Fällt 62-mal Kopf, wird die Hypothese abgelehnt – ebenso bei nur 38-mal.</p>`],
    ['Rückwärts fragen', `<p>„Wie oft muss man würfeln, um mit mindestens 90 % Wahrscheinlichkeit mindestens eine Sechs zu haben?“ Der Schlüssel ist das Gegenereignis „keine Sechs“:</p>${D('1-\\left(\\tfrac56\\right)^n\\ge 0{,}9\\ \\Rightarrow\\ n\\ge\\dfrac{\\ln(0{,}1)}{\\ln\\left(\\tfrac56\\right)}\\approx 12{,}6')}<p>Also mindestens 13 Würfe – es wird immer aufgerundet.</p>`],
    ['Typische Fehler', `<ul><li>Bei ${t('P(A\\cup B)')} den Schnitt doppelt gezählt.</li><li>Beim zweiseitigen Test nur einen Rand betrachtet.</li><li>Bei „mindestens einmal“ abgerundet statt aufgerundet.</li><li>Bei stetigen Größen nach ${t('P(X=3)')} gefragt – das ist immer 0.</li></ul>`],
  ],
  'g-abstand2': [
    ['Worum es geht', `<p>Abstände im Raum misst man immer senkrecht. Deshalb dreht sich in diesem Kapitel alles um Normalenvektoren: Mit ihnen berechnet man den Abstand eines Punktes von einer Ebene, findet die Schnittgerade zweier Ebenen, den Abstand windschiefer Geraden und Spiegelpunkte.</p>`],
    ['Hesse-Form und Abstand Punkt–Ebene', `${D('d(P;E)=\\dfrac{|n_1p_1+n_2p_2+n_3p_3-d|}{|\\vec n|}')}<p>Die Ebene ${t('n_1x_1+n_2x_2+n_3x_3=d')} wird durch die Länge ihres Normalenvektors geteilt. Setzt man dann einen Punkt ein, kommt sein Abstand heraus. Ohne Betragsstriche zeigt das Vorzeichen, auf welcher Seite der Punkt liegt.</p>`],
    ['Schnittgerade zweier Ebenen', `${D('\\vec u=\\vec n_1\\times\\vec n_2')}<p>Sind die Normalenvektoren keine Vielfachen voneinander, schneiden sich die Ebenen in einer Geraden. Ihr Richtungsvektor steht senkrecht auf beiden Normalenvektoren. Einen Stützpunkt findet man, indem man eine Koordinate frei wählt (zum Beispiel ${t('x_3=0')}) und das Gleichungssystem löst.</p>`],
    ['Windschiefe Geraden', `${D('d=\\dfrac{|(\\vec q-\\vec p)\\cdot\\vec n|}{|\\vec n|}\\qquad\\vec n=\\vec u\\times\\vec v')}<p>Zwei Geraden sind windschief, wenn sie nicht parallel sind und sich nicht schneiden. Der Vektor ${t('\\vec n')} steht senkrecht auf beiden; der Abstand ist der Anteil des Verbindungsvektors der Stützpunkte in dieser Richtung.</p>`],
    ['Durchgerechnetes Beispiel: Spiegeln an einer Ebene', `<p>${t('P(4\\mid -1\\mid 3)')} wird an ${t('E:\\ 2x_1+x_2+2x_3=4')} gespiegelt. Lotgerade: ${t('\\vec x=(4\\mid -1\\mid 3)+r\\,(2\\mid 1\\mid 2)')}.</p>${D('2(4+2r)+(-1+r)+2(3+2r)=4\\ \\Rightarrow\\ 13+9r=4\\ \\Rightarrow\\ r=-1')}<p>Lotfußpunkt ${t('F(2\\mid -2\\mid 1)')}. Für den Spiegelpunkt wird ${t('r')} verdoppelt: ${t("P'(0\\mid -3\\mid -1)")}.</p>`],
    ['Typische Fehler', `<ul><li>Bei der Hesse-Form das Teilen durch ${t('|\\vec n|')} vergessen.</li><li>Den Abstand der Stützpunkte für den Abstand der Geraden gehalten.</li><li>Beim Spiegeln nur bis zum Lotfußpunkt gerechnet.</li><li>Beim Kreuzprodukt in der mittleren Zeile das Vorzeichen vertauscht.</li></ul>`],
  ],
};

/** Karten einer Einheit (aus den „Benennen“-Schritten) – die Kurzfassung. */
export const karten = (u) => u.steps.flatMap((s) => s.run.cards || []);
export const hatLang = (u) => Array.isArray(LANG[u.id]);
/** Alle Abschnitte der ausführlichen Fassung: Grundkapitel plus Vertiefung (weitere Beispiele, Sonderfälle). Die Vertiefung steht vor dem Schluss-Abschnitt („Typische Fehler“, „So gehst du vor“ …). */
export function abschnitte(id) {
  const L = LANG[id] || [], M = MEHR[id] || [];
  if (!M.length) return L;
  const schluss = L.length && /^(Typische Fehler|So gehst du vor|Reihenfolge für die Prüfung)/.test(L[L.length - 1][0]) ? 1 : 0;
  return [...L.slice(0, L.length - schluss), ...M, ...L.slice(L.length - schluss)];
}
/** Ausführlich und PDF gehören zur Pro-Fassung; solange der Verkauf nicht gestartet ist, ist alles offen. */
export const proOffen = () => store.zugangGilt() || !premiumOn();

const website = () => CONFIG.website.replace(/^https?:\/\/|\/$/g, '');
const kopf = (u, art) => `<header class="b-kopf"><img class="b-logo" src="img/logo.svg" alt="Logo ${esc(CONFIG.firma)}"><div class="b-firma"><b>${esc(CONFIG.firma)}</b><span>${esc(website())}</span></div>
  <div class="b-titel"><h1>${esc(u.title)}</h1><span>${esc(u.sub || '')} · ${art}</span></div></header>`;

/** Das Kapitel als Lesetext (Vorschau = Druckbild). lang = true: ausführliche Fassung, falls vorhanden. */
export function kapitelHtml(u, lang) {
  const K = karten(u), L = lang && hatLang(u) ? abschnitte(u.id) : null;
  const art = (titel) => (/^(Beispiel|Durchgerechnetes Beispiel)/.test(titel) ? ' t-bsp' : /^Sonderfälle/.test(titel) ? ' t-sonder' : /^Genauer hingeschaut/.test(titel) ? ' t-tief' : '');
  const teile = L ? `<p class="t-inhalt">${L.length} Abschnitte · ${L.filter(([x]) => /Beispiel/.test(x)).length} durchgerechnete Beispiele</p>` + L.map(([titel, html]) => `<section class="t-teil${art(titel)}"><h2>${esc(titel)}</h2>${html}</section>`).join('')
    : K.map((c) => `<section class="t-teil"><h2>${esc(c.title)}</h2>${c.html}</section>`).join('');
  const formeln = u.formeln?.length ? `<section class="t-teil t-merk"><h2>Formeln zum Merken</h2>${u.formeln.map(([n, f]) => `<div class="t-zeile"${hatMerkbild(n) ? ` data-merk="${esc(n)}"` : ''}><small>${esc(n)}</small><div class="t-formel">${tex(f, true)}</div></div>`).join('')}</section>` : '';
  const wozu = u.why ? `<section class="t-teil"><h2>Wo brauche ich das?</h2><p>${esc(u.why)}</p></section>` : '';
  return `<article class="blatt theorie" id="kapitel"><section class="b-seite">${kopf(u, L ? 'ausführlich' : 'kurz')}${teile}${formeln}${wozu}
    <footer class="b-fuss"><span>${esc(CONFIG.firma)} · ${esc(website())}</span><span>Theorie: ${esc(u.title)} (${L ? 'ausführlich' : 'kurz'})</span></footer></section></article>`;
}

/** Übersicht aller Kapitel. */
function listeView() {
  const el = h(`<div class="view stack">
    <a class="back" href="#/lernen">${ICON.left} Lernen</a>
    <div><span class="eyebrow">Theorie</span><h1 style="margin-top:8px">Nachlesen</h1><p class="lead" style="margin-top:8px">Jedes Thema als kurzes Kapitel – und Schritt für Schritt auch ausführlich mit Herleitung und Beispiel.</p></div>
    ${AREAS.filter((a) => a.id !== 'pruefung').map((a) => `<div class="sect"><h2>${esc(a.title)}</h2></div><section class="stack">${UNITS.filter((u) => u.area === a.id && karten(u).length).map((u) =>
      `<a class="card unit" href="#/theorie/${u.id}"><span class="num">${hatLang(u) ? '2' : '1'}</span><span><h3>${esc(u.title)}</h3><small>${hatLang(u) ? 'kurz und ausführlich' : 'kurz'}${unitExtra(u) ? ` · ${esc(NICHT_TEXT[store.land] || 'Zusatz')}` : ''}</small></span><span class="go">${ICON.right}</span></a>`).join('')}</section>`).join('')}
  </div>`);
  return { el };
}

function kapitelView(u, startLang) {
  const el = h(`<div class="view stack blatt-view">
    <a class="back noprint" href="#/theorie">${ICON.left} Theorie</a>
    <div class="noprint"><span class="eyebrow">Theorie</span><h1 style="margin-top:8px">${esc(u.title)}</h1><p class="lead" style="margin-top:6px">${esc(u.sub || '')}</p></div>
    <div class="t-leiste noprint"><div class="umschalt" id="t-art" role="radiogroup" aria-label="Länge"><button class="pick" type="button" role="radio" data-l="0">Kurz</button><button class="pick" type="button" role="radio" data-l="1">Ausführlich ${marke('pro')}</button></div>
      <a class="btn small" href="#/u/${u.id}">Üben</a><button class="btn ghost small" id="t-druck" type="button">PDF ${marke('pro')}</button></div>
    <div id="t-pro" class="noprint"></div>
    <div id="t-text"></div>
  </div>`);
  let lang = !!startLang && hatLang(u);
  const pro = $('#t-pro', el);
  const paint = () => {
    el.querySelectorAll('#t-art .pick').forEach((b) => { const on = (b.dataset.l === '1') === lang; b.classList.toggle('sel', on); b.setAttribute('aria-checked', on); });
    $('#t-text', el).innerHTML = kapitelHtml(u, lang);
    merkbilderEinsetzen($('#t-text', el));   // bewegte Merkbilder unter die passenden Formeln
  };
  el.querySelectorAll('#t-art .pick').forEach((b) => { b.onclick = async () => {
    const will = b.dataset.l === '1'; sfx('tap'); pro.innerHTML = '';
    if (will && !hatLang(u)) { pro.innerHTML = '<div class="note tip">Die ausführliche Fassung zu diesem Thema ist in Arbeit. Die kurze Fassung enthält schon alles Wichtige.</div>'; return; }
    if (will) { await premiumBereit(); if (!proOffen()) { pro.innerHTML = '<div class="note tip"><b>Die ausführliche Fassung gehört zur Pro-Fassung.</b> <a href="#/einstellungen">Zugangscode eingeben</a></div>'; return; } }
    lang = will; paint();
  }; });
  $('#t-druck', el).onclick = async () => {
    await premiumBereit();
    if (!proOffen()) { pro.innerHTML = '<div class="note tip"><b>Drucken und PDF gehören zur Pro-Fassung.</b> <a href="#/einstellungen">Zugangscode eingeben</a></div>'; return; }
    drucken(`Theorie-${u.title}`);
  };
  premiumBereit().then(() => { if (el.isConnected && !premiumOn() && !pro.innerHTML) pro.innerHTML = '<small class="muted">„Ausführlich“ und PDF gehören später zur Pro-Fassung. In der Testphase sind sie für alle frei.</small>'; });
  paint();
  return { el };
}

/** Einstieg für den Router: #/theorie oder #/theorie/<Einheit>[-lang] */
export function theorieView(teil) {
  const lang = /-lang$/.test(teil || ''), id = String(teil || '').replace(/-lang$/, ''), u = UNITS.find((x) => x.id === id && karten(x).length);
  return u ? kapitelView(u, lang) : listeView();
}
